  ctx.fillStyle='rgba(6,9,14,0.90)'; ctx.fillRect(dx,dy,dw,dh);
  ctx.strokeStyle=sc.tint||'#ffb347'; ctx.lineWidth=Math.max(2,S(2)); ctx.strokeRect(dx,dy,dw,dh);
  const spk=sc[sc.speaking||'left'];
