  ctx.fillText('HI '+String(Math.max(run.score,highScore||0)).padStart(7,'0'),352,42);
  if(boss && bossActive && !boss.dead){ const w=240*clamp(boss.hp/boss.maxhp,0,1);
    ctx.fillStyle='#3a0a0a'; ctx.fillRect(72,64,240,8); ctx.fillStyle='#ff3a3a'; ctx.fillRect(72,64,w,8); }
  const sh=clamp(run.shield/100,0,1);
  ctx.fillStyle='#0d2030'; ctx.fillRect(23,122,11,248);
  ctx.fillStyle='#2b9fd8'; ctx.fillRect(23,122+248*(1-sh),11,248*sh);
  for(let i=0;i<6;i++){ ctx.fillStyle=(i<run.wlevel)?'#8de23a':'#16201a'; ctx.fillRect(349,159+i*39,27,29); }
  const wmap={0:'item_mg',1:'item_spread',2:'item_nade'};
  const slots=[wmap[run.weapon], run.speed>0?'item_speed':null, run.shield>0?'item_shield':null, null, run.bombs>0?'item_nade':null];
  const sx=[50,120,190,260,330];
  for(let i=0;i<slots.length;i++){ if(slots[i]&&ASSETS.has(slots[i])) ASSETS.blit(slots[i],sx[i],460,30,30); }
