ctx.imageSmoothingEnabled = false;

/* ---- responsive integer scaling, letterboxed ---- */
function fitCanvas(){
  const ww = window.innerWidth, wh = window.innerHeight;
  let s = Math.min(ww/VW, wh/VH);
  s = Math.max(0.5, s);
  cv.style.width = Math.floor(VW*s)+'px';
  cv.style.height = Math.floor(VH*s)+'px';
}
window.addEventListener('resize', fitCanvas); fitCanvas();

/* ---- RNG / math helpers ---- */
const rnd = (a=1,b=0)=> b===0 ? Math.random()*a : a+Math.random()*(b-a);
const rint = (a,b)=> Math.floor(rnd(a,b+1));
const clamp = (v,a,b)=> v<a?a:v>b?b:v;
const chance = p => Math.random()<p;
const TAU = Math.PI*2;
const dist2 = (ax,ay,bx,by)=>{const dx=ax-bx,dy=ay-by;return dx*dx+dy*dy;};
const lerp=(a,b,t)=>a+(b-a)*t;

/* ============================================================
   AUDIO ENGINE — WebAudio synth (sfx + simple music)
   ============================================================ */
const Audio = (()=>{
  let actx=null, master=null, musicGain=null, sfxGain=null;
  let volMaster=0.8, volMusic=0.5, volSfx=0.85, muted=false;
  let noiseBuf=null;
  /* init() MUST NOT THROW (drop 0724di).
     goTitle() is `Audio.init(); Audio.startMusic('title'); setState(GS.TITLE);` — audio FIRST, and
     assemble.py uses that exact text as a span marker so the line cannot be reshaped. If init()
     throws, setState is never reached and the game sits on the LOADING screen forever: no title,
     no menu, nothing to click, and no readout to photograph. That is exactly what Mike is seeing.
     Guarding init() itself fixes goTitle and every other caller at once, which is the better fix
     regardless. A browser with no usable AudioContext should lose sound, not the game. */
  function init(){
    if(actx) return;
    try{
      actx = new (window.AudioContext||window.webkitAudioContext)();
    }catch(_){ actx=null; return; }
    master = actx.createGain(); master.gain.value=volMaster; master.connect(actx.destination);
    musicGain = actx.createGain(); musicGain.gain.value=volMusic; musicGain.connect(master);
    sfxGain = actx.createGain(); sfxGain.gain.value=volSfx; sfxGain.connect(master);
    const len = actx.sampleRate*1.0; noiseBuf=actx.createBuffer(1,len,actx.sampleRate);
    const d=noiseBuf.getChannelData(0); for(let i=0;i<len;i++) d[i]=Math.random()*2-1;
  }
  /* resume() is called from EVERY input handler, so it is not allowed to throw. A suspended or
     broken AudioContext costs sound; it must never cost control. */
  function resume(){ try{ if(actx&&actx.state==='suspended'&&actx.resume) actx.resume(); }catch(_){} }
  function now(){ return actx?actx.currentTime:0; }
  // basic tone
  function tone(freq,dur,type='square',vol=0.3,bend=0,dest){
    if(!actx||muted) return;
    const o=actx.createOscillator(), g=actx.createGain();
    o.type=type; o.frequency.setValueAtTime(freq, now());
    if(bend) o.frequency.exponentialRampToValueAtTime(Math.max(20,freq+bend), now()+dur);
    g.gain.setValueAtTime(0.0001, now());
    g.gain.exponentialRampToValueAtTime(vol, now()+0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, now()+dur);
    o.connect(g); g.connect(dest||sfxGain); o.start(); o.stop(now()+dur+0.02);
  }
  function noise(dur,vol=0.4,filter=1200,sweep=-800,dest){
    if(!actx||muted) return;
    const src=actx.createBufferSource(); src.buffer=noiseBuf;
    const bp=actx.createBiquadFilter(); bp.type='lowpass';
    bp.frequency.setValueAtTime(filter, now());
    bp.frequency.linearRampToValueAtTime(Math.max(120,filter+sweep), now()+dur);
    const g=actx.createGain();
    g.gain.setValueAtTime(vol, now());
    g.gain.exponentialRampToValueAtTime(0.0001, now()+dur);
    src.connect(bp); bp.connect(g); g.connect(dest||sfxGain); src.start(); src.stop(now()+dur+0.02);
  }
  // ---- named sfx ----
  const SFX = {
    shoot(){ tone(880,0.06,'square',0.10,-300); tone(1320,0.04,'square',0.05,-200); },
    spread(){ tone(660,0.07,'sawtooth',0.09,-260); },
    grenade(){ tone(180,0.12,'square',0.16,-60); noise(0.07,0.10,800,-400); },
    enemyShoot(){ tone(320,0.08,'sawtooth',0.06,-120); },
    hit(){ tone(1400,0.03,'square',0.06,-600); },
    expSmall(){ noise(0.18,0.35,1600,-1200); tone(160,0.16,'triangle',0.18,-100); },
    expBig(){ noise(0.5,0.6,2200,-1900); tone(90,0.5,'triangle',0.3,-60); tone(200,0.3,'sawtooth',0.18,-150); },
    bomb(){ noise(0.9,0.7,3000,-2600); tone(70,0.9,'sine',0.4,-30); tone(260,0.5,'square',0.2,-200); },
    powerup(){ tone(523,0.08,'square',0.2); setTimeout(()=>tone(784,0.08,'square',0.2),70); setTimeout(()=>tone(1046,0.12,'square',0.22),140); },
    weapon(){ tone(440,0.06,'square',0.2); setTimeout(()=>tone(660,0.06,'square',0.2),60); setTimeout(()=>tone(880,0.1,'square',0.22),120); },
    life(){ tone(660,0.1,'triangle',0.25); setTimeout(()=>tone(880,0.1,'triangle',0.25),100); setTimeout(()=>tone(1100,0.1,'triangle',0.25),200); setTimeout(()=>tone(1320,0.18,'triangle',0.28),300); },
    death(){ noise(0.7,0.6,1800,-1600); tone(300,0.6,'sawtooth',0.3,-260); },
    blip(){ tone(740,0.04,'square',0.16); },
    select(){ tone(523,0.05,'square',0.18); setTimeout(()=>tone(784,0.07,'square',0.2),50); },
    boot(){ // sega-style chord rise
      tone(220,0.5,'triangle',0.25); tone(330,0.5,'triangle',0.2,0); 
      setTimeout(()=>{tone(440,0.6,'triangle',0.28); tone(554,0.6,'triangle',0.22);},250);
    },
    bossAlarm(){ tone(440,0.18,'sawtooth',0.22,-120); setTimeout(()=>tone(330,0.22,'sawtooth',0.22,-80),180); },
    stageClear(){ const seq=[523,659,784,1046,784,1046,1318]; seq.forEach((f,i)=>setTimeout(()=>tone(f,0.16,'square',0.25),i*120)); },
    gameover(){ const seq=[440,392,330,262]; seq.forEach((f,i)=>setTimeout(()=>tone(f,0.4,'triangle',0.3,-40),i*260)); },
    victory(){ const seq=[523,659,784,1046,1318,1046,1318,1568]; seq.forEach((f,i)=>setTimeout(()=>tone(f,0.22,'square',0.28),i*160)); },
    crash(){ noise(0.5,0.6,1700,-1500); tone(70,0.45,'triangle',0.34,-40); tone(150,0.25,'square',0.2,-160); },
    slice(){ tone(2200,0.10,'sawtooth',0.16,-1700); noise(0.14,0.22,6000,-3200); setTimeout(()=>tone(420,0.12,'square',0.13,-300),55); },
    getready(){ tone(620,0.10,'square',0.16); },
    go(){ tone(880,0.10,'square',0.22); setTimeout(()=>tone(1320,0.16,'square',0.24),90); },
    douse(){ noise(0.5,0.55,2600,-1300); noise(0.22,0.3,820,-260); tone(170,0.32,'sine',0.08,-110); },
    crackle(){ noise(0.05,0.09,3600,-2200); },
    freeze(){ tone(300,0.5,'sine',0.07,900); tone(600,0.4,'sine',0.05,1400); noise(0.35,0.4,5000,2200); },
    countdown(){}, continueVO(){}, restrictedarea(){}, enemyunits(){}, enemyunit(){}, over(){},
    shatter(){ noise(0.18,0.6,5200,-2400); for(let k=0;k<7;k++){ setTimeout(()=>tone(1400+Math.random()*1600,0.10,'triangle',0.10),k*22); } },
    whip(){ noise(0.14,0.5,3200,2600); tone(1600,0.10,'sawtooth',0.05,-1400); },   // fast whipping-turn swoosh
    lockon(){ tone(1200,0.05,'square',0.08); setTimeout(()=>tone(1200,0.05,'square',0.08),110); setTimeout(()=>tone(1600,0.07,'square',0.10),220); },  // missile lock beep
    lockAlert(){ // urgent target-lock alarm on the player: fast rising triple-beep
      tone(900,0.06,'square',0.10); setTimeout(()=>tone(1150,0.06,'square',0.10),90); setTimeout(()=>tone(1500,0.10,'square',0.12),180);
      setTimeout(()=>{ tone(1500,0.08,'sawtooth',0.08); },300);
    },
  };
  // ---- simple looping music (bass + arp) ----
  let musicTimer=null, musicStep=0, musicPattern=null, musicOn=false, musicTempo=140;
  const SCALES = {
    title:  {bass:[55,55,73,82],   arp:[220,330,440,330, 262,392,523,392], tempo:150},
    stage:  {bass:[49,49,55,65],   arp:[196,294,392,294, 247,330,494,330], tempo:165},
    jungle: {bass:[49,55,49,62],   arp:[196,330,392,330, 262,330,440,392], tempo:158},
    boss:   {bass:[41,41,49,55],   arp:[247,330,415,330, 220,294,370,294], tempo:185},
  };
  /* startMusic is called immediately before state changes too — same rule, same reason. */
  function startMusic(name){
    if(!actx) return;
    if(!actx) return; stopMusic(); musicOn=true; musicStep=0;
    musicPattern=SCALES[name]||SCALES.title; musicTempo=musicPattern.tempo;
    const beat = 60/musicTempo/2;
    musicTimer=setInterval(()=>{
      if(!musicOn||muted) return;
      const b=musicPattern.bass[Math.floor(musicStep/2)%musicPattern.bass.length];
      if(musicStep%2===0) tone(b,beat*1.6,'triangle',0.16,0,musicGain);
      const a=musicPattern.arp[musicStep%musicPattern.arp.length];
      tone(a,beat*0.8,'square',0.05,0,musicGain);
      if(musicStep%4===2) noise(0.05,0.06,4000,-2000,musicGain); // hat
      musicStep++;
    }, beat*1000);
  }
  function stopMusic(){ musicOn=false; if(musicTimer){clearInterval(musicTimer);musicTimer=null;} }
  function setVol(kind,v){
    if(kind==='master'){volMaster=v; if(master)master.gain.value=v;}
    if(kind==='music'){volMusic=v; if(musicGain)musicGain.gain.value=v;}
    if(kind==='sfx'){volSfx=v; if(sfxGain)sfxGain.gain.value=v;}
  }
  function getVol(kind){return kind==='master'?volMaster:kind==='music'?volMusic:volSfx;}
  function toggleMute(){ muted=!muted; return muted; }
  /* musicPlaying HAS NEVER EXISTED (drop 0731x). Four call sites guard on it:

         if(!(Audio.musicPlaying && Audio.musicPlaying())) Audio.startMusic('neonvelocity')

     Audio.musicPlaying is undefined, so the && short-circuits, !undefined is true, and every one
     of those guards has always evaluated to "nothing is playing" regardless of the truth. They
     were no-ops wearing the shape of a check. Exposing the real state makes all four work as
     written, which is the root of the campaign-map silence. */
  return {init,resume,SFX,startMusic,stopMusic,setVol,getVol,toggleMute,isMuted:()=>muted,
          musicPlaying:()=>!!(musicOn && musicTimer)};
})();

/* ============================================================
   INPUT
   ============================================================ */
const KEYBIND_DEFAULT={up:['w','arrowup','pad_up'],down:['s','arrowdown','pad_down'],left:['a','arrowleft','pad_left'],right:['d','arrowright','pad_right'],fire:['j','pad_b0','pad_b7'],bomb:['k','pad_b1','pad_b6'],retina:['c','pad_b2']};
/* KEYBINDS MUST BE VALIDATED, NOT JUST FILLED IN (drop 0724dl).

   Mike's readout said it all: `state title, kd40 ku41, last shift, menu 0`. Forty keypresses
   arriving, the menu never moving, and the last recorded key was SHIFT. The binds were broken and
   SAVED — which is why reinstalling the game never helped: the fault lived in localStorage, not in
   any build.

   The old guard was `if(!j[a]) j[a]=DEFAULT[a]`. That only replaces a MISSING action. An empty
   array is truthy, so {"down":[]} passed straight through and menuDown() returned false forever.
   And the rebind screen did `keybind[action]=[k]` for whatever key was pressed — including a bare
   modifier. Bind 'down' to shift once and the arrow keys are dead permanently, across every
   reload.

   Now: every action must end up with at least one USABLE key, bare modifiers are refused, and
   anything that fails is restored from the defaults. */
const KEY_UNBINDABLE = ['shift','control','alt','meta','capslock','contextmenu','dead','unidentified',''];
function keybindValidate(kb){
  const out = {}, fixed = [];
  for(const a in KEYBIND_DEFAULT){
    let list = Array.isArray(kb && kb[a]) ? kb[a].filter(function(k){
      return typeof k==='string' && k.length>0 && KEY_UNBINDABLE.indexOf(k.toLowerCase())<0;
    }) : null;
    if(!list || !list.length){ list = KEYBIND_DEFAULT[a].slice(); fixed.push(a); }
    out[a] = list;
  }
  if(fixed.length){
    try{ console.warn('keybind: restored defaults for', fixed.join(', ')); }catch(e){}
    try{ localStorage.setItem('bof_keys', JSON.stringify(out)); }catch(e){}   // heal the save too
  }
  out.__fixed = fixed;
  return out;
}
let keybind=(function(){
  let j=null;
  try{ j=JSON.parse(localStorage.getItem('bof_keys')||'null'); }catch(e){ j=null; }
  return keybindValidate(j);
})();
function saveKeybind(){ try{ localStorage.setItem('bof_keys',JSON.stringify(keybind)); }catch(e){} }
const Input = (()=>{
  const keys={}, pressed={};
  const mouse={x:VW/2,y:VH*0.75,down:false,inside:false,active:false,moved:false,_lx:-1,_ly:-1};
  /* key() MUST NOT THROW ON A MALFORMED EVENT (drop 0724do).
     This was `e.key.toLowerCase()` with no guard. If e.key is undefined — and it is on synthetic
     events, on some IME and remapping layers, and on a few keyboard drivers — that throws a
     TypeError before anything is recorded. The counters in the probe increment BEFORE this call, so
     the readout showed numbers rising while not one key was ever stored. That is exactly what Mike
     saw: "registering all movements, numbers are changing, but the cursor is just not moving".
     e.code and e.keyCode are used as fallbacks, and the whole body is guarded. */
  const _KC={37:'arrowleft',38:'arrowup',39:'arrowright',40:'arrowdown',13:'enter',32:' ',27:'escape',
             8:'backspace',9:'tab',16:'shift',17:'control',18:'alt',112:'f1'};
  function keyName(e){
    if(e && typeof e.key==='string' && e.key.length) return e.key.toLowerCase();
    if(e && typeof e.code==='string' && e.code.length){
      const c=e.code;
      if(/^Key[A-Z]$/.test(c)) return c.slice(3).toLowerCase();
      if(/^Digit\d$/.test(c)) return c.slice(5);
      return c.toLowerCase();
    }
    if(e && typeof e.keyCode==='number'){
      if(_KC[e.keyCode]) return _KC[e.keyCode];
      if(e.keyCode>=65 && e.keyCode<=90) return String.fromCharCode(e.keyCode+32);
      if(e.keyCode>=48 && e.keyCode<=57) return String.fromCharCode(e.keyCode);
    }
    return null;
  }
  function key(e,d){
    try{
      const k=keyName(e);
      if(k===null) return;                       // nothing usable: do not throw, just ignore
      if(d && !keys[k]) pressed[k]=true;
      keys[k]=d;
      if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k)){
        try{ e.preventDefault(); }catch(_){}
      }
    }catch(_){ /* a malformed event must never cost the player their controls */ }
  }
  /* INPUT MUST NEVER DEPEND ON AUDIO (drop 0724dg).
     This was `Audio.resume(); key(e,true);` — audio FIRST, unguarded. If Audio.resume() throws for
     any reason, key() never runs, the keypress is never recorded, and the game is completely
     unresponsive. It also explains the silence: the same broken audio subsystem that throws here
     is the one that would have played the chime. One line produced BOTH symptoms.
     key() now runs FIRST and unconditionally; audio is attempted afterwards inside a try. A dead
     audio context can cost sound. It must never cost control. */
  /* INPUT PROBE (drop 0724dh). I cannot reproduce Mike's dead menu here — in a faithful browser
     simulation both the keyboard and the click path work. So the game now COUNTS the events it
     actually receives and draws them on the title screen. One photograph tells us whether the
     events are reaching the page at all, which is the thing I have been unable to determine. */
  window.__inp = {key:0, kup:0, mdown:0, mmove:0, touch:0, lastKey:'-', lastXY:'-'};
  /* The counter used to increment BEFORE key() ran, so it counted events that were then dropped by
     a throw — a readout that said "input is arriving" while nothing was recorded. It now reports
     what was actually STORED. */
  window.addEventListener('keydown',e=>{ key(e,true); const _k=keyName(e); window.__inp.key++; window.__inp.lastKey=(_k===null?'UNREADABLE':_k)+(keys[_k]?'':'!'); try{ Audio.resume(); }catch(_){} });
  window.addEventListener('keyup',e=>{ window.__inp.kup++; key(e,false); });
  /* ` toggles the live menu diagnostic (drop 0801r) */
  window.__menudiag=null;
  window.addEventListener('keydown',e=>{
    if(e.key==='`'){ window.__menudiag = window.__menudiag ? null : {calls:0,lastMove:'-',err:null}; }
  });
  /* A LOST KEYUP SILENTLY KILLS THAT KEY (drop 0724dg). key() suppresses auto-repeat with
     `if(d && !keys[k])`, so a key recorded as down that never receives its keyup can never produce
     another tap — that key is dead for the rest of the session. Alt-tabbing, losing focus or a
     dropped event is enough. Releasing everything when the window loses focus or is hidden costs
     nothing and removes the failure. */
  function releaseAll(){ try{ for(const k in keys) keys[k]=false; clearTaps(); mouse.down=false; }catch(_){} }
  window.addEventListener('blur', releaseAll);
  document.addEventListener('visibilitychange', function(){ if(document.hidden) releaseAll(); });
  function mpos(e){
    const r=cv.getBoundingClientRect();
    const cx=(e.touches?e.touches[0].clientX:e.clientX);
    const cy=(e.touches?e.touches[0].clientY:e.clientY);
    const nx=clamp((cx-r.left)/r.width*VW,0,VW), ny=clamp((cy-r.top)/r.height*VH,0,VH);
    if(Math.abs(nx-mouse.x)>0.5 || Math.abs(ny-mouse.y)>0.5) mouse.moved=true;   // real movement
    mouse.x=nx; mouse.y=ny; mouse.active=true;
  }
  cv.addEventListener('mousemove',e=>{ window.__inp.mmove++; mouse.inside=true; mpos(e); window.__inp.lastXY=Math.round(mouse.x)+','+Math.round(mouse.y); });
  cv.addEventListener('mousedown',e=>{ window.__inp.mdown++; mouse.down=true; mpos(e); window.__inp.lastXY=Math.round(mouse.x)+','+Math.round(mouse.y); try{ Audio.resume(); }catch(_){} });
  window.addEventListener('mouseup',()=>mouse.down=false);
  cv.addEventListener('wheel',e=>{mouse.wheel=(mouse.wheel||0)+e.deltaY;e.preventDefault();},{passive:false});
  cv.addEventListener('mouseleave',()=>mouse.inside=false);
  // touch (bonus)
  cv.addEventListener('touchstart',e=>{ mouse.down=true; mpos(e); e.preventDefault(); try{ Audio.resume(); }catch(_){} },{passive:false});
  cv.addEventListener('touchmove',e=>{mpos(e);e.preventDefault();},{passive:false});
  cv.addEventListener('touchend',e=>{mouse.down=false;e.preventDefault();},{passive:false});
  // ---- gamepad (USB controller) support ----
  let gpConnected=false;
  window.addEventListener('gamepadconnected',()=>{ gpConnected=true; });
  window.addEventListener('gamepaddisconnected',()=>{ gpConnected=false; });
  const _padHeld={};
  function pollGamepad(){
    if(!navigator.getGamepads) return;
    const pads=navigator.getGamepads();
    const gp=pads&&(pads[0]||pads[1]||pads[2]||pads[3]);
    if(!gp){ if(gpConnected) gpConnected=false; return; }
    gpConnected=true;
    const setk=(name,held)=>{
      if(held && !_padHeld[name]){ pressed[name]=true; }
      _padHeld[name]=held; keys[name]=held;
    };
    // left stick + d-pad -> directional virtual keys
    const ax=gp.axes[0]||0, ay=gp.axes[1]||0, dz=0.35;
    const dpUp=gp.buttons[12]&&gp.buttons[12].pressed, dpDn=gp.buttons[13]&&gp.buttons[13].pressed;
    const dpLf=gp.buttons[14]&&gp.buttons[14].pressed, dpRt=gp.buttons[15]&&gp.buttons[15].pressed;
    setk('pad_up',    ay<-dz || !!dpUp);
    setk('pad_down',  ay> dz || !!dpDn);
    setk('pad_left',  ax<-dz || !!dpLf);
    setk('pad_right', ax> dz || !!dpRt);
    // face + shoulder buttons -> pad_b0..pad_b15 (all bindable via the options "press a key" flow)
    for(let i=0;i<gp.buttons.length;i++){ setk('pad_b'+i, !!gp.buttons[i].pressed); }
  }
  window.addEventListener('gamepadconnected',()=>{ try{ Audio.resume&&Audio.resume(); }catch(_){} });
  function down(k){return !!keys[k];}
  function tap(k){ if(pressed[k]){pressed[k]=false;return true;} return false; }
  function clearTaps(){ for(const k in pressed) pressed[k]=false; }
  // menu navigation: taps that respect the user's keybind (wasd/arrows/dpad/stick) + gamepad confirm/back
  function tapAny(list){ let hit=false; for(const k of list){ if(tap(k)) hit=true; } return hit; }
  function menuUp(){ return tapAny(keybind.up); }
  function menuDown(){ return tapAny(keybind.down); }
  function menuLeft(){ return tapAny(keybind.left); }
  function menuRight(){ return tapAny(keybind.right); }
  function menuConfirm(){ return tap('enter')||tap(' ')||tapAny(keybind.fire)||tap('pad_b0')||tap('pad_b9'); }
  /* K IS BACK (drop 0801bv). I bound 'b' last drop and that was wrong: on this
     layout the gamepad B button IS 'k' (fire=J, missile=K, retina=L), so 'b' was
     an unrelated key. 'b' is REMOVED rather than kept alongside — a stray letter
     closing menus is exactly the kind of thing that fires by accident. */
  function menuBack(){ return tap('backspace')||tap('escape')||tap('k')||tap('pad_b1')||tap('pad_b8'); }
  function consumeMouseMoved(){ const m=mouse.moved; mouse.moved=false; return m; }
  return {keys,mouse,down,tap,clearTaps,pollGamepad,tapAny,menuUp,menuDown,menuLeft,menuRight,menuConfirm,menuBack,consumeMouseMoved,
    get gamepadConnected(){return gpConnected;},
    get up(){return keybind.up.some(k=>down(k));},
    get dn(){return keybind.down.some(k=>down(k));},
    get lf(){return keybind.left.some(k=>down(k));},
    get rt(){return keybind.right.some(k=>down(k));}};
})();

