      'minitank2',
      'minitank3',
      'minishipA',
      'minishipB',
      'minishipC',
      'boat1',
      'boat2',
      'boat3',
      'boat4',
      'boat5',
      'boat6',
      'boat7',
      'bunkerA',
      'bunkerB',
      'el_cs',
      'el_em',
      'el_gr',
      'el_gw',
      'el_hd',
      'el_iv',
      'el_jh',
