    b.x=lerp(b._dash.from,b._dash.to,e);
    if(run.stage===4){ b._trail=b._trail||[]; b._trail.push({x:b.x,y:b.y}); if(b._trail.length>6)b._trail.shift(); b._trailT=0.16; }
    if(p>=1){ b._dash=null; b._ret=0.9; }
