      ctx.save(); ctx.translate(e.x,e.y); ctx.scale(1,-1); ctx.translate(-e.x,-e.y);
      if(e.tvar && e.tvar!=='green' && !t){ const tc=e.tvar==='red'?'#c0332a':e.tvar==='blue'?'#3050b8':'#20242c'; ASSETS.blitTint(g,e.x,e.y,dw,dh,tc,0.55); }
      ASSETS.blit(g,e.x,e.y,dw,dh);
      if(t) ASSETS.blitTint(g,e.x,e.y,dw,dh,t,(t==='#ffffff'?0.9:0.5));
      ctx.restore();
      if(e._muz&&e._muz>0){ const mf='t_muz'+(Math.floor(e._muz*16)%2); if(ASSETS.has(mf)){ const ms=e.w*0.55, mr=dh*0.40;
        ASSETS.blit(mf, e.x+Math.cos(aim)*mr, e.y+Math.sin(aim)*mr, ms, ms); } }
