      ASSETS.blit(nm,e.x,e.y,dw,dh);
      if(run.stage===2 && !t) ASSETS.blitTint(nm,e.x,e.y,dw,dh,'#ff7a3a',0.22);
      if(t) ASSETS.blitTint(nm,e.x,e.y,dw,dh,t,(t==='#ffffff'?0.9:0.5));
