  minitank2: {row:1, cols:[7,12], w:30,h:30, hp:11, sc:480, fr:1.5, scale:0.86, terr:'ground', axis:'v'},
  minitank3: {row:3, cols:[7,12], w:30,h:30, hp:13, sc:540, fr:1.4, scale:0.86, terr:'ground', axis:'v'},
