function miniArtKey(e){
  const D=MINI_DEF[e._mini]; if(!D) return null;
  const [c0,c1]=D.cols;
  const span=c1-c0;
  // pick the rotation step from the unit's facing so it turns rather than flipping
  const idx=c0+clamp(Math.round(((e._face||0)+1)/2*span),0,span);
  return `nmt_r${D.row}_${idx}`;
}
function drawMini(e){
  if(typeof XART==='undefined') return false;
  const k=miniArtKey(e); if(!k||!XART.rdy(k)) return false;
  const D=MINI_DEF[e._mini];
  const im=XART.get(k);
  const h=e.h*1.5*D.scale, w=h*(im.naturalWidth/im.naturalHeight);
  ctx.save(); ctx.translate(e.x,e.y);
  ctx.drawImage(im,-w/2,-h/2,w,h);
  /* HIT FLASH via xartTint, never ctx.filter. Canvas filters are an HTML/CSS effect: they render
     inconsistently across contexts, do not respect the pixel-art look, and were why several units
     never appeared to light up when shot. Tinting the sprite keeps its silhouette exactly. */
  if(e.flash>0 && typeof xartTint==='function'){
    const _tc=xartTint(k, e.flash>0.04?'#ffffff':'#ff8a4a', 0.85);
    if(_tc) ctx.drawImage(_tc,-w/2,-h/2,w,h);
  }
  ctx.restore();
  return true;
}
function miniTick(e, dt){
  const D=MINI_DEF[e._mini]; if(!D) return;
  // slow turn toward the player so the rotation frames get used
  if(player && !player.dead){
    const want=clamp((player.x-e.x)/120,-1,1);
    e._face=(e._face||0)+(want-(e._face||0))*Math.min(1,dt*2.2);
  }
  // ---- PATROL on the unit's own axis, and never leave its terrain ----
  if(e._pdir==null) e._pdir=(Math.random()<0.5?-1:1);
  const spd=(D.axis==='h'?26:16)*dt;
  if(D.axis==='h'){
    const nx=e.x+e._pdir*spd;
    if(miniTerrainOK(D.terr, nx, e.y, e.w) && nx>16 && nx<worldWidth()-16) e.x=nx;
    else e._pdir*=-1;                                  // hit the bank -> turn around
  } else {
    const ny=e.y+e._pdir*spd;
    if(miniTerrainOK(D.terr, e.x, ny, e.w) && ny>30 && ny<VH-30) e.y=ny;
    else e._pdir*=-1;                                  // hit the cliff -> turn around
  }
  // The master scrolls underneath, so a unit can be carried into blocked terrain. Search BOTH
  // axes for the nearest valid footing and slide it there — a boat tracks its channel, a tank
  // steps back off the rock.
  if(!miniTerrainOK(D.terr, e.x, e.y, e.w)){
    let moved=false;
    for(let r=5;r<=140 && !moved;r+=5){
      const cand=[[r,0],[-r,0],[0,r],[0,-r],[r*0.7,r*0.7],[-r*0.7,r*0.7],[r*0.7,-r*0.7],[-r*0.7,-r*0.7]];
      for(const [dx,dy] of cand){
        const tx=clamp(e.x+dx,16,worldWidth()-16), ty=clamp(e.y+dy,24,VH-24);
        if(miniTerrainOK(D.terr, tx, ty, e.w)){ e.x=tx; e.y=ty; moved=true; break; }
      }
    }
    if(!moved) e.dead=true;      // channel ran out entirely — retire it rather than beach it
  }
  // PELLET BALLS — a short spread burst, not a stream
  e._pel=(e._pel==null?rnd(0.6,1.6):e._pel)-dt;
  if(e._pel<=0 && !e.dead && e._dyingT==null){
    e._pel=D.fr*rnd(0.85,1.25)/Math.max(0.4,DIFF.eFire);
    const ang=Math.atan2((player?player.y:VH)-e.y,(player?player.x:e.x)-e.x);
    for(const off of [-0.16,0,0.16]) eShootT(e.x, e.y+e.h*0.3, ang+off, 2.1, 'pellet', null);
    e._muz=0.12;
  }
  if(e._muz>0) e._muz-=dt;
}
