function eliteSprite(tag, state){
  eliteSprite._c = eliteSprite._c || {};
  const ck=tag+'|'+state;
  if(eliteSprite._c[ck]!==undefined) return eliteSprite._c[ck];
  const D=ELITE_DEF[tag];
  if(!D || typeof XART==='undefined'){ return null; }        // NOT cached: retry next frame
  const comps=_ELITE_COMPS[D.c];
  /* DO NOT CACHE A HALF-BUILT ELITE (drop 0801bl). This filtered the component
     list by XART.rdy() — decode state — and then cached whatever came back,
     permanently, under a key that is never invalidated. Two ways it poisoned
     itself on a cold stage:

       nothing decoded yet -> keys is empty -> it cached NULL, and that elite
                              never drew again for the whole session;
       some decoded        -> it composited only those and cached the PARTIAL,
                              so the unit flew around permanently missing a wing
                              or a gun mount.

     The component LIST now comes from registration, which is synchronous and
     complete, and the composite is only committed to the cache once every one of
     those components has actually decoded. Until then it still returns a
     composite of what is ready — so the elite appears immediately and simply
     completes itself — but nothing is stored, so the next frame re-evaluates. */
  const all=comps.map(c=>D.p+'_'+c+'_'+state).filter(k=>XART._src && XART._src[k]);
  if(!all.length) return null;                               // truly unregistered: retry, do not cache
  for(const k of all){ if(XART._touch) XART._touch(k); }     // start every decode now
  const keys=all.filter(k=>XART.rdy(k));
  const complete=(keys.length===all.length);
  if(!keys.length) return null;                              // nothing decoded YET: retry, do not cache
  const first=XART.get(keys[0]);
  const cv=document.createElement('canvas');
  cv.width=first.naturalWidth; cv.height=first.naturalHeight;
  const g=cv.getContext('2d');
  for(const k of keys){ const im=XART.get(k); if(im) g.drawImage(im,0,0,cv.width,cv.height); }
  if(complete) eliteSprite._c[ck]=cv;                        // only a FULL composite is worth keeping
  return cv;
}
function drawElite(e){
  const D=ELITE_DEF[e._el]; if(!D) return false;
  const frac=clamp(e.hp/(e.maxhp||e.hp),0,1);
  /* TWO STATES, NOT THREE (drop 0801bl). The mbj_ set ships _clean and _ruin
     only - there is no _dam anywhere in the manifest. Between 60% and 25% HP
     this asked for a state that does not exist, eliteSprite found no components,
     and drawElite bailed: the unit vanished mid-fight and reappeared at 25%.
     Identical to the Overlord-X helicopter in 0801az. */
  const st = frac>0.5?'clean' : 'ruin';
  const sp=eliteSprite(e._el, st);
  if(!sp) return false;
  const h=e.h*1.7, w=h*(sp.width/sp.height);
  ctx.save(); ctx.translate(e.x,e.y);
  if(D.flip) ctx.scale(1,-1);          // authored facing away -> turn it on the player
  // e.flash tint is applied through xartTint after the draw, not a canvas filter
  ctx.drawImage(sp,-w/2,-h/2,w,h);
  ctx.restore();
  return true;
}
