      // using source-atop, which needs no getImageData (that is what broke this whole screen on
      // file:// before) and preserves the sprite's own alpha shape.
      let _rc = drawStageSelect._redCur;
      if(!_rc){ _rc = drawStageSelect._redCur = {}; }
      const _ck = 'c'+(((stateT*10)|0)%8);
      let _cc = _rc[_ck];
      if(!_cc){
        const cvs=document.createElement('canvas');
        cvs.width=cim.naturalWidth||cs; cvs.height=cim.naturalHeight||cs;
        const g2=cvs.getContext('2d');
        g2.drawImage(cim,0,0);
        g2.globalCompositeOperation='source-atop';
        g2.fillStyle='#ff2a2a'; g2.globalAlpha=0.92;
        g2.fillRect(0,0,cvs.width,cvs.height);
        _cc=_rc[_ck]=cvs;
      }
      ctx.save();
      ctx.shadowColor='#ff2a2a'; ctx.shadowBlur=10+6*Math.sin(stateT*9);
      ctx.globalCompositeOperation='lighter';
      ctx.drawImage(_cc, cxm-cs/2, cym-cs/2, cs, cs);
      // red lock ring pulsing inside the box
      ctx.globalAlpha=0.75+0.25*Math.sin(stateT*9);
