/* ============================================================
   RIVAL RACE (drop 0724j) — replaces the old free-flight dogfight.

   Mike: the duel becomes a RACE down the pack's authored courses. You and the rival both have to
   BLOW OBSTACLES OUT OF THE WAY or take the hit; the rival AI does the same, so it can wreck
   itself on a boulder it failed to clear. Checkpoint gates mark progress, missile crates restock.

   Pack rules followed (rival-dogfight-implementation.md):
     · side walls only — "never treat the art as two fixed lanes", so lateral movement is free
     · gates are drawn as a PAIR — "duplicate the beacon on both sides when a full gate is desired"
     · obstacles are independent breakables with intact/damaged/breaking/debris
     · tunnel variants swap collision bounds on the exterior-entry threshold

   THREE encounters, matching the pack's own course naming exactly:
       course 'a' = rival-02-03   after stage 2
       course 'b' = rival-04-05   after stage 4
       course 'c' = rival-06-07   after stage 6
   ============================================================ */
/* ============================================================
   SPARED RIVAL -> CALLABLE ALLY (drop 0724j).
   Spare a rival and they join the roster. During any later stage you can call one in: they arrive
   with a line, fight alongside you for ALLY_DUR seconds, then sign off with a parting line and
   fly out. One call per spared rival per run — they are a favour, not a turret.
   ============================================================ */
const ALLY_DUR = 30.0;          // Mike: "help you for about 30 seconds"
const ALLY_ARRIVE = 1.6, ALLY_LEAVE = 2.2;
let allyRoster = [];            // pilot keys of rivals the player spared
let ally = null;                // the one currently flying with you
const ALLY_HELLO = {
  maverick:  "HEARD YOU WERE IN TROUBLE. FORM UP — I OWE YOU ONE.",
  yuri:      "YOU LET ME LIVE. LET ME MAKE IT COUNT.",
  decker:    "MY GUNS, YOUR CALL. LET'S CLEAR THIS SKY.",
  juggernaut:"YOU SPARED ME. NOW I FLY FOR YOU. STAY ON MY WING.",
};
const ALLY_BYE = {
  maverick:  "THAT'S MY FUEL. FLY SMART OUT THERE — YOU'VE EARNED IT.",
  yuri:      "DEBT PAID, PILOT. IT WAS AN HONOUR.",
  decker:    "GOOD SHOOTING. GO FINISH IT.",
  juggernaut:"YOU DIDN'T NEED ME. YOU NEVER DID. GIVE 'EM HELL.",
};
function allyBank(key){ if(key && allyRoster.indexOf(key)<0) allyRoster.push(key); }
function allyAvailable(){ return allyRoster.filter(k=>!(ally&&ally.key===k)&&(!ally||!ally.usedKeys||ally.usedKeys.indexOf(k)<0)); }
let allyUsed = [];              // spent this run
function allyCall(){
  if(ally) return false;
  const pool=allyRoster.filter(k=>allyUsed.indexOf(k)<0);
  if(!pool.length) return false;
  const key=pool[0];
  const P=(typeof PILOTS!=='undefined')?PILOTS.find(p=>p.key===key):null;
  allyUsed.push(key);
  ally={key:key, name:P?P.name:key.toUpperCase(), tint:P?P.tint:'#ffffff',
        x:clamp(player.x+60,40,worldWidth()-40), y:VH+70, t:0, phase:'arrive',
        line:ALLY_HELLO[key]||"ON YOUR WING.", lineT:0, fcd:0};
  if(Audio.SFX.allyArrive) Audio.SFX.allyArrive();
  return true;
}
function allyUpdate(dt){
  if(!ally) return;
  ally.t+=dt; ally.lineT+=dt;
  const W=worldWidth();
  if(ally.phase==='arrive'){
    ally.y += (player.y-40-ally.y)*Math.min(1,dt*2.2);
    ally.x += (clamp(player.x+56,40,W-40)-ally.x)*Math.min(1,dt*2.0);
    if(ally.t>=ALLY_ARRIVE){ ally.phase='fight'; ally.t=0; ally.lineT=0; }
  } else if(ally.phase==='fight'){
    // flies loose formation off the player's wing and puts fire downrange
    const tx=clamp(player.x+Math.sin(ally.t*1.1)*64, 40, W-40);
    const ty=player.y-46+Math.sin(ally.t*1.7)*10;
    ally.x += (tx-ally.x)*Math.min(1,dt*3.0);
    ally.y += (ty-ally.y)*Math.min(1,dt*3.0);
    if((ally.fcd-=dt)<=0){
      ally.fcd=0.16;
      if(typeof pBullets!=='undefined' && typeof pBullets.push==='function'){
        pBullets.push({x:ally.x, y:ally.y-14, vx:0, vy:-11, dmg:2, r:3, ally:true, col:ally.tint});
      }
    }
    if(ally.t>=ALLY_DUR){ ally.phase='leave'; ally.t=0; ally.lineT=0; ally.line=ALLY_BYE[ally.key]||"GOOD HUNTING."; if(Audio.SFX.allyLeave) Audio.SFX.allyLeave(); }
  } else {
    ally.y -= 210*dt;
    ally.x += Math.sin(ally.t*2.0)*40*dt;
    if(ally.t>=ALLY_LEAVE || ally.y<-80) ally=null;
  }
}
function allyReset(){ ally=null; }
function allyDraw(){
  if(!ally || typeof XART==='undefined') return;
  const k='ship_'+ally.key;
  ctx.save();
  if(ally.phase==='leave') ctx.globalAlpha=clamp(1-ally.t/ALLY_LEAVE,0,1);
  if(XART.rdy(k)){
    const im=XART.get(k), h=34, w=h*(im.naturalWidth/im.naturalHeight);
    ctx.drawImage(im, ally.x-w/2, ally.y-h/2, w, h);
  } else { ctx.fillStyle=ally.tint; ctx.fillRect(ally.x-9, ally.y-11, 18, 22); }
  ctx.restore();
  // arrival / departure line, and a quiet timer so the player can plan around the 30 seconds
  if(ally.lineT < 3.2 && (ally.phase==='arrive' || ally.phase==='leave')){
    if(typeof msgText==='function') msgText(ally.name+': '+ally.line, VW/2, VH*0.20, 10, ally.tint, 0.9, 1, 0.08);
  }
  if(ally.phase==='fight'){
    const left=Math.max(0, ALLY_DUR-ally.t);
    ctx.save(); ctx.globalAlpha=0.85; ctx.fillStyle=ally.tint;
    ctx.fillRect(VW-64, 8, Math.round(52*(left/ALLY_DUR)), 3);
    ctx.globalAlpha=1; ctx.restore();
  }
}
/* RIVAL ENCOUNTERS DISABLED (drop 0724ao). Mike: the race system may not make the game jam, and
   in its current state it is broken enough to be worse than absent. Set RIVAL_ENABLED back to true
   to restore all three encounters — the courses, art, ally system and phase machine are all still
   built and tested, nothing has been deleted. */
const RIVAL_ENABLED = false;
const RACE_AFTER = RIVAL_ENABLED ? {2:'a', 4:'b', 6:'c'} : {};                 // stage cleared -> course letter
const RACE_VARIANTS = ['oa','ob','tn'];
const RACE_OBS = ['mine','sat','ice','barrier','tank','boulder'];   // breakables only
const RACE_LEN = 34.0;                                     // seconds of course
let race = null;
function raceCourseKeys(tag){
  const out=[];
  for(let i=1;i<=4;i++){ const k='nrc_'+tag+'_s'+i; if(typeof XART!=='undefined'&&XART.rdy(k)) out.push(k); }
  return out;
}
function raceStart(letter){
  if(Audio.SFX.raceStart) Audio.SFX.raceStart();
  const variant = RACE_VARIANTS[(Math.random()*RACE_VARIANTS.length)|0];
  let tag = letter+variant, secs = raceCourseKeys(tag);
  if(!secs.length){ tag = letter+'oa'; secs = raceCourseKeys(tag); }   // never start a course with no art
  race = {tag:tag, letter:letter, variant:variant, secs:secs, scroll:0, t:0,
          obs:[], gates:0, nextObs:0.8, nextGate:4.0,
          pProg:0, rProg:0, pHits:0, rHits:0,
          tunnel:(variant==='tn'), done:false, winner:null};
  return race;
}
/* one obstacle. hp 2 so a single tap damages and a second breaks it — you must commit to clearing
   a lane, not brush it. */
function raceSpawnObs(){
  const W=worldWidth();
  const kind=RACE_OBS[(Math.random()*RACE_OBS.length)|0];
  race.obs.push({kind:kind, x:rnd(70,W-70), y:-90, hp:2, st:0, dead:false, brk:0, isGate:false});
}
function raceSpawnGate(){
  const W=worldWidth();
  const cx=rnd(W*0.30, W*0.70);
  // "duplicate the beacon on both sides when a full gate is desired" — a gate is a PAIR
  race.obs.push({kind:'gate', x:cx-96, y:-90, hp:99, st:0, dead:false, brk:0, isGate:true, gid:race.gates});
  race.obs.push({kind:'gate', x:cx+96, y:-90, hp:99, st:0, dead:false, brk:0, isGate:true, gid:race.gates, mirror:true});
  race.gates++;
}
function raceHitObs(o, dmg){
  if(o.isGate || o.dead) return;
  o.hp-=dmg;
  o.st = (o.hp<=0) ? 2 : 1;                    // intact -> damaged -> breaking
  if(o.hp<=0 && o.brk===0){ o.brk=0.001; if(typeof explode==='function') explode(o.x,o.y,18,'orange'); if(Audio.SFX.raceObstacle) Audio.SFX.raceObstacle(); }
}
function raceUpdate(dt){
  if(!race) return;
  const W=worldWidth();
  race.t+=dt; race.scroll+=dt*260;
  // ---- course furniture
  if((race.nextObs-=dt)<=0){ race.nextObs=rnd(0.55,1.15); raceSpawnObs(); }
  if((race.nextGate-=dt)<=0){ race.nextGate=rnd(5.5,8.0); raceSpawnGate(); }
  for(const o of race.obs){
    o.y += 260*dt;
    if(o.brk>0){ o.brk+=dt; if(o.brk>0.18) o.st=3; if(o.brk>0.5) o.dead=true; }
  }
  race.obs = race.obs.filter(o=>!o.dead && o.y<VH+120);
  // ---- RIVAL AI: it races the same course and must clear its own lane or eat the hit
  const r=race;
  if(r.rx==null){ r.rx=W*0.5; r.ry=VH*0.30; }
  let threat=null, td=1e9;
  for(const o of r.obs){
    if(o.isGate || o.dead) continue;
    const dy=o.y-r.ry;
    if(dy>-40 && dy<230 && Math.abs(o.x-r.rx)<80 && dy<td){ threat=o; td=dy; }
  }
  if(threat){
    // shoot it if it is dead ahead, otherwise slide around it
    if(Math.abs(threat.x-r.rx)<26){
      r._rcd=(r._rcd==null?0:r._rcd)-dt;
      if(r._rcd<=0){ r._rcd=0.22; raceHitObs(threat,1); }
    } else {
      r.rx += (threat.x<r.rx?1:-1)*140*dt;
    }
    // it does NOT always make it — a rival that never fails is not a race
    if(td<26 && Math.abs(threat.x-r.rx)<30 && threat.hp>0){ r.rHits++; threat.hp=0; threat.st=2; threat.brk=0.001; }
  } else {
    r.rx += Math.sin(race.t*1.7)*90*dt;
  }
  r.rx = clamp(r.rx, 60, W-60);
  // ---- progress: both advance, hits cost time
  const pSpd = 1.0 - Math.min(0.45, race.pHits*0.09);
  const rSpd = 1.0 - Math.min(0.45, race.rHits*0.09);
  race.pProg += dt*pSpd/RACE_LEN;
  race.rProg += dt*rSpd/RACE_LEN;
  if(!race.done && (race.pProg>=1 || race.rProg>=1)){
    race.done=true;
    race.winner = (race.pProg>=race.rProg) ? 'player' : 'rival';
    if(race.winner==='player'){ if(Audio.SFX.raceWin) Audio.SFX.raceWin(); }
    else { if(Audio.SFX.raceLose) Audio.SFX.raceLose(); }
  }
}
/* ---- the playable race: mirrors the main game's control feel, then hands into 'choice' ---- */
function updateRaceFight(dt){
  const r=rival; r.t+=dt;
  if(typeof updateRetina==='function') updateRetina(dt);
  if(typeof updateMissileRush==='function') updateMissileRush(dt);
  if(typeof updateSpecial==='function') updateSpecial(dt);
  if(!race) raceStart(RACE_AFTER[run.stage]||'a');
  raceUpdate(dt);
  const W=worldWidth();
  // ---- player: same movement + fire feel as the main game
  if(!player.dead){
    let mvx=0,mvy=0;
    if(Input.lf)mvx-=1; if(Input.rt)mvx+=1; if(Input.up)mvy-=1; if(Input.dn)mvy+=1;
    const sp=(typeof playerBaseSpeed==='function')?playerBaseSpeed():2.6;
    if(mvx||mvy){ const l=Math.hypot(mvx,mvy)||1; player.x+=mvx/l*sp*1.35; player.y+=mvy/l*sp*1.35; }
    player.x=clamp(player.x,18,W-18); player.y=clamp(player.y,40,VH-24);
    if(typeof tryShoot==='function') tryShoot(dt);
  }
  // ---- player bullets clear obstacles
  if(typeof pBullets!=='undefined'){
    for(const b of pBullets){
      if(b.dead) continue;
      for(const o of race.obs){
        if(o.dead||o.isGate) continue;
        if(Math.abs(b.x-o.x)<30 && Math.abs(b.y-o.y)<24){ raceHitObs(o, b.dmg||1); b.dead=true; break; }
      }
    }
  }
  // ---- an obstacle you failed to clear costs you time
  for(const o of race.obs){
    if(o.dead||o.isGate||o.hp<=0) continue;
    if(Math.abs(o.x-player.x)<26 && Math.abs(o.y-player.y)<22){
      race.pHits++; o.hp=0; o.st=2; o.brk=0.001;
      if(typeof explode==='function') explode(o.x,o.y,20,'red');
      shake=Math.max(shake,6); if(Audio.SFX.hit)Audio.SFX.hit();
    }
  }
  if(typeof updateEffects==='function') updateEffects(dt);
  // ---- finish: hand into the EXISTING choice phase, dialogue untouched
  if(race.done){
    rival.hp=0; rival.dead=true;
    rival.phase='choice'; rival.t=0; rival.choiceIdx=0;
    rival.raceWinner=race.winner;
    if(Audio.SFX.hit)Audio.SFX.hit(); shake=Math.max(shake,8);
  }
}
function drawRaceFight(dt){
  const W=worldWidth();
  ctx.save();
  ctx.fillStyle='#06070b'; ctx.fillRect(0,0,VW,VH);
  // course sections scroll under everything
  if(race && race.secs.length && typeof XART!=='undefined'){
    const k=race.secs[Math.floor(race.scroll/1000)%race.secs.length];
    if(XART.rdy(k)){
      const im=XART.get(k), sc=VW/im.naturalWidth, dh=im.naturalHeight*sc;
      let y=(race.scroll%dh)-dh;
      for(; y<VH; y+=dh) ctx.drawImage(im,0,y,VW,dh);
    }
  }
  // obstacles / gates
  if(race && typeof XART!=='undefined'){
    for(const o of race.obs){
      const k='nrh_'+o.kind+'_'+raceObsFrame(o);
      if(!XART.rdy(k)) continue;
      const im=XART.get(k), h=54, w=h*(im.naturalWidth/im.naturalHeight);
      ctx.save(); ctx.translate(o.x,o.y);
      if(o.mirror) ctx.scale(-1,1);
      ctx.drawImage(im,-w/2,-h/2,w,h); ctx.restore();
    }
  }
  // the rival jet
  if(race && typeof XART!=='undefined'){
    const rk='nrj_'+(Math.floor((race.t||0)*10)%4);
    if(XART.rdy(rk)){
      const im=XART.get(rk), h=42, w=h*(im.naturalWidth/im.naturalHeight);
      ctx.drawImage(im, (race.rx||VW/2)-w/2, (race.ry||VH*0.3)-h/2, w, h);
    }
  }
  ctx.restore();
  if(typeof drawEffects==='function') drawEffects();

  if(!player.dead && typeof drawPlayer==='function') drawPlayer();
  if(typeof drawPBullets==='function') drawPBullets();
  // ---- race HUD: who is ahead, and by how much
  if(race){
    ctx.save();
    ctx.fillStyle='rgba(6,8,12,0.72)'; ctx.fillRect(10,10,VW-20,26);
    ctx.strokeStyle=rival.tint; ctx.lineWidth=1; ctx.strokeRect(10,10,VW-20,26);
    const bw=VW-40;
    ctx.fillStyle='#4d5566'; ctx.fillRect(20,20,bw,4);
    ctx.fillStyle=rival.tint; ctx.fillRect(20,16,Math.round(bw*clamp(race.rProg,0,1)),3);
    ctx.fillStyle='#7fe08a'; ctx.fillRect(20,25,Math.round(bw*clamp(race.pProg,0,1)),3);
    ctx.textAlign='left'; ctx.font='9px "BOFmil", monospace';
    ctx.fillStyle='#7fe08a'; ctx.fillText('YOU', 20, 46);
    ctx.textAlign='right'; ctx.fillStyle=rival.tint; ctx.fillText(rival.name, VW-20, 46);
    ctx.restore();
  }
}
function raceObsFrame(o){
  // breakables: 0 intact 1 damaged 2 breaking 3 debris
  // gates:      0 red    1 amber   2 green    3 finish_flash
  if(o.isGate){
    const p=race?race.pProg:0;
    return (p>0.92)?3:(o.y>VH*0.45?2:(o.y>VH*0.15?1:0));
  }
  return clamp(o.st|0,0,3);
}
function rollRivalEncounter(){
  // guaranteed encounter after stages 2, 4 and 6 — the three courses the pack actually ships
  const myKey=_pilotKey();
  const pool=RIVAL_POOL.filter(k=>k!==myKey);
  if(!pool.length) return false;
  const key=pool[(Math.random()*pool.length)|0];
  const P=PILOTS.find(p=>p.key===key);
  const letter=RACE_AFTER[run.stage];
  if(!letter) return false;                    // only stages 2, 4 and 6 have a course
  rival={key, name:P?P.name:key.toUpperCase(), tint:P?P.tint:'#ffffff', x:VW/2, y:-80, ang:Math.PI/2, bank:0, phase:'desert', t:0, script:RIVAL_SCRIPT[key]||[{who:'rival',text:'READY FOR THIS?'}], dlgIdx:0, dlgT:0};
  raceStart(letter);
  return true;
}
function startRivalSequence(){ setState(GS.RIVAL); if(Audio.startMusic)Audio.startMusic('rival'); }
function drawDesertBG(dt,spdMul){
  const im=(typeof XART!=='undefined'&&XART.rdy('terr_desert'))?XART.get('terr_desert'):null;
  const mul=(spdMul!=null?spdMul:1);
  drawRivalSeq._scroll=(drawRivalSeq._scroll||0)+dt*150*mul;   // real flight-speed ground rush (was 46)
  if(im){
    const thh=VW*(im.naturalHeight/im.naturalWidth);
    const off=drawRivalSeq._scroll%thh;
    for(let y=-thh+off; y<VH; y+=thh) ctx.drawImage(im,0,y,VW,thh);
  } else { ctx.fillStyle='#7a5a34'; ctx.fillRect(0,0,VW,VH); }
  // speed streaks scale with throttle so N/M reads instantly on screen
  if(mul>0.01){
    ctx.save(); ctx.globalAlpha=Math.min(0.5,0.10+0.16*mul); ctx.strokeStyle='#fff2d8'; ctx.lineWidth=1;
    const n=Math.min(16,Math.round(3+mul*3));
    for(let i=0;i<n;i++){ const sx=(i*97+drawRivalSeq._scroll*3.1)%(VW+60)-30; const len=18+mul*30;
      ctx.beginPath(); ctx.moveTo(sx,((i*173+drawRivalSeq._scroll*4)% (VH+len))-len); ctx.lineTo(sx,((i*173+drawRivalSeq._scroll*4)%(VH+len))); ctx.stroke(); }
    ctx.restore();
  }
}
// typeReveal: advances a per-line char counter and plays a soft tick per new letter
function typeReveal(state, text, dt, cps){
  cps=cps||34;
  if(state._twText!==text){ state._twText=text; state._twChars=0; state._twLast=0; }
  const before=Math.floor(state._twChars);
  state._twChars=Math.min(text.length, state._twChars + dt*cps);
  const after=Math.floor(state._twChars);
  if(after>before){
    // play a tick for each newly revealed non-space character
    for(let i=before;i<after;i++){ const ch=text[i]; if(ch && ch!==' '){ (Audio.SFX.blip||function(){})(); break; } }
  }
  return state._twChars;
}
function typeRevealDone(state, text){ return state._twText===text && state._twChars>=text.length; }
function drawRivalSeq(dt){
  if(!rival){ beginStage(3); return; }
  rival.t+=dt;
  const _inFight=(rival.phase==='smash'||rival.phase==='fight'||rival.phase==='choice'||rival.phase==='spare_dialogue'||rival.phase==='shootdown_dialogue'||rival.phase==='crash_fade'||rival.phase==='reveal'||rival.phase==='defeat');
  const pk=_pilotKey();
  const psx=VW/2, psy=VH*0.72;
  if(!_inFight){
    drawDesertBG(dt, 3.4);   // FULL-SPEED ground rush from the moment the cutscene starts
    // player ship, flying steady near the bottom third throughout the cinematic
    if(typeof XART!=='undefined' && XART.rdy('ship_'+pk)){ const im=XART.get('ship_'+pk); const w=44,h=w*(im.naturalHeight/im.naturalWidth); ctx.drawImage(im,psx-w/2,psy-h/2,w,h); }
  } else if(rival.phase==='smash'){
    drawDesertBG(dt, 3.4);   // smash beat stays full-speed too
  }

  switch(rival.phase){
    case 'desert':
      if(rival.t>1.6){ rival.phase='banner'; rival.t=0; Audio.SFX.bossAlarm(); }
      break;
    case 'banner': {
      if(!rival._raVO){ rival._raVO=true; if(Audio.SFX&&Audio.SFX.restrictedarea)Audio.SFX.restrictedarea(); }
      const a=Math.min(1, rival.t>1.6?(2.0-rival.t)/0.4:1);
      ctx.save(); ctx.globalAlpha=Math.max(0,a);
      if(typeof XART!=='undefined' && XART.rdy('enemy_approaching')){
        const im=XART.get('enemy_approaching'); const w=VW*0.52, h=w*(im.naturalHeight/im.naturalWidth);
        ctx.shadowColor='#ff2a1a'; ctx.shadowBlur=18;
        ctx.drawImage(im,VW/2-w/2,VH*0.4-h/2,w,h);
      } else { ctx.textAlign='center'; ctx.fillStyle='#ff4030'; ctx.font='bold 26px "BOFmil", monospace'; ctx.fillText('ENEMY APPROACHING',VW/2,VH*0.4); }
      ctx.restore();
      // rival comes up from behind and INCHES toward the player's side while the banner shows
      if(rival.y<-40){ rival.x=psx-70; rival.y=VH+50; }
      rival.y=lerp(rival.y, psy, 0.03);          // slowly rise alongside
      rival.x=lerp(rival.x, psx-52, 0.04);       // ease up to the player's left side
      drawRivalShip();
      if(rival.t>2.2){ rival.phase='approach'; rival.t=0; }
      break;
    }
    case 'approach': {
      // keep inching up until the rival is right beside the player, then talk
      rival.x=lerp(rival.x, psx-46, 0.06);
      rival.y=lerp(rival.y, psy, 0.10);
      rival.bank=0;
      drawRivalShip();
      if(Math.abs(rival.y-psy)<6 && rival.t>0.8){ rival.phase='dialogue'; rival.t=0; }
      break;
    }
    case 'smash': {
      // the rival rams the player's plane: shove into them, player flashes white + takes a hit
      const p=clamp(rival.t/0.5,0,1);
      rival.x=lerp(psx-46, psx-12, p<0.5?p*2:1);   // lunge in
      rival.y=psy;
      if(!rival._smacked && p>=0.5){ rival._smacked=true;
        player._flash=0.4; shake=Math.max(shake,14); Audio.SFX.hit();
        if(run.shield>0){ run.shield--; } // costs a shield if you have one, else it's the free "first hit"
        floatText(psx,psy-20,'RAMMED!','#ff5a3a');
      }
      drawRivalShip();
      // player flash overlay
      if(typeof XART!=='undefined' && XART.rdy('ship_'+pk)){ const im=XART.get('ship_'+pk); const w=44,h=w*(im.naturalHeight/im.naturalWidth);
        ctx.save(); if(player._flash>0){ ctx.filter='brightness(2.8)'; player._flash-=dt; } ctx.drawImage(im,psx-w/2,psy-h/2,w,h); ctx.restore(); }
      if(rival.t>0.7){
        Audio.SFX.select();
        rival.phase='fight'; rival.t=0;
        rival.hp=rival.maxhp=340; rival.tail=0; rival.fireCd=0.8; rival.weaveT=0; rival.ramCd=1.5; rival._flash=0;
        rival.x=psx+50; rival.y=VH*0.30;
        player._flash=0; player.fireCd=0;
        rivalPickups.length=0; rival._mc1=false; rival._mc2=false; rival._mcT=3.5;
      }
      break;
    }
    case 'dialogue': {
      drawRivalShip();
      rival.dlgT+=dt;
      const line=rival.script[rival.dlgIdx];
      const isPlayer=line.who==='player';
      const pk=_pilotKey(), P=PILOTS.find(p=>p.key===pk);
      const speaker=isPlayer ? {tint:(P?P.tint:'#8ad0ff'), name:(P?P.name:'PILOT'), key:pk} : {tint:rival.tint, name:rival.name, key:rival.key};
      const appear=clamp(rival.dlgT/0.22,0,1);
      const _emo='idle';   // no emotion 'emoji' portrait swaps — always the idle face
      const _pk=(line.who==='rival')?rival.key:_pilotKey();
      const _tw=typeReveal(rival, line.text, dt);
      drawCommWindow({tint:speaker.tint, name:speaker.name, frameKey:'dlg_'+speaker.key, portraitKey:pilotPortrait(_pk,_emo), cardKey:'card_'+speaker.key, text:line.text, appear, charsShown:_tw});
      if(rival.dlgT>0.45){
        ctx.save(); ctx.globalAlpha=0.5+0.5*Math.sin(rival.dlgT*4); ctx.textAlign='center'; ctx.fillStyle='#cfd6e0'; ctx.font='9px "BOFmil", monospace';
        ctx.fillText(rival.dlgIdx<rival.script.length-1 ? '\u25B6' : 'PRESS FIRE / ENTER', VW/2, VH*0.34-24); ctx.restore();
        if(Input.tap('enter')||keybind.fire.some(k=>Input.tap(k))){
          if(!typeRevealDone(rival, line.text)){ rival._twChars=line.text.length; Audio.SFX.blip(); }   // 1st press: reveal all
          else {
            Audio.SFX.blip();
            if(rival.dlgIdx<rival.script.length-1){ rival.dlgIdx++; rival.dlgT=0; }
            else { Audio.SFX.select(); rival.phase='smash'; rival.t=0; rival._smacked=false; }
          }
        }
      }
      break;
    }
    case 'fight': {
      /* RIVAL RACE (drop 0724j, switched on in 0724m). The old free-flight dogfight is gone —
         updateRivalFight/drawRivalFight are no longer reachable from any phase. The race resolves
         to a winner and then hands into the SAME 'choice' phase the duel used, so the dialogue and
         the SPARE / SHOOT THEM DOWN branch are completely unchanged. */
      updateRaceFight(dt);
      if(!rival || state!==GS.RIVAL) return;
      drawRaceFight(dt);
      break;
    }
    case 'choice': case 'spare_dialogue': case 'shootdown_dialogue': case 'crash_fade': case 'reveal': case 'defeat': case 'player_spared': {
      drawRivalEnding(dt);
      break;
    }
  }
}
function hitRival(dmg){
  if(!rival||rival.hp<=0) return;
  rival.hp-=dmg; rival._flash=0.12;
  if(typeof stageStats!=='undefined') stageStats.dmgDealt+=dmg;
  if(rival.hp<=0){ rival.hp=0; rival.dead=true; rival.phase='choice'; rival.t=0; rival.choiceIdx=0; Audio.SFX.hit(); shake=Math.max(shake,8);
    if(retina.target===rival){ retina.target=null; retina.phase=null; } }
}
/* updateRivalFight REMOVED (drop 0724m): the free-flight dogfight is gone, replaced by
   the rival RACE. 235 lines deleted rather than left resident, so it cannot be reached again. */

/* drawRivalFight REMOVED (drop 0724m): the free-flight dogfight is gone, replaced by
   the rival RACE. 72 lines deleted rather than left resident, so it cannot be reached again. */

/* ---- Phase 4: spare-or-shoot-down resolution ---- */
/* MEASURED INK RECTS for the affiliation emblems (drop 0801ba):
   [srcX, srcY, srcW, srcH, canvasW, canvasH]. Regenerate with the bbox pass in
   fix_menucard_0801ba.py if the emblem art is ever redrawn. */
const PEMB_INK={
  pemb_axel:[28,72,200,112,256,256],
  pemb_cole:[28,71,200,113,256,256],
  pemb_decker:[29,28,198,200,256,256],
  pemb_falva:[28,46,200,164,256,256],
  pemb_freezer:[28,82,200,92,256,256],
  pemb_juggernaut:[29,28,198,200,256,256],
  pemb_lizzie:[28,62,200,131,256,256],
  pemb_maverick:[28,77,200,101,256,256],
  pemb_yuri:[28,77,200,101,256,256]
};
function affiliationName(key){ const P=PILOTS.find(p=>p.key===key); return P?P.name:key.toUpperCase(); }
function typewriter(text,frac,x,y,size,col){
  const n=Math.round(text.length*clamp(frac,0,1));
  ctx.save(); ctx.textAlign='center'; ctx.font='bold '+size+'px "BOFmil", monospace'; ctx.fillStyle=col;
  ctx.shadowColor=col; ctx.shadowBlur=10;
  ctx.fillText(text.slice(0,n), x, y);
  ctx.restore();
}
function drawRivalEnding(dt){
  drawDesertBG(dt, 1.8);
  if(rival.hp<=0 && rival.phase!=='reveal' && rival.phase!=='crash_fade' || (rival.phase==='crash_fade'&&rival.t<0.05)){ ctx.save(); if(rival._flash>0){ ctx.filter='brightness(2.6)'; } drawRivalShip(); ctx.restore(); }
  if(!player.dead){ ctx.save(); const pk=_pilotKey(); if(typeof XART!=='undefined' && XART.rdy('ship_'+pk)){ const im=XART.get('ship_'+pk); const w=40,h=w*(im.naturalHeight/im.naturalWidth); ctx.drawImage(im,player.x-w/2,player.y-h/2,w,h); } ctx.restore(); }
  updateEffects(dt); drawEffects();
  rival.t+=dt;

  if(rival.phase==='choice'){
    // d-pad / arrows / wasd all toggle the two options
    if(Input.tap('arrowup')||Input.tap('w')||Input.tap('pad_up')||Input.tap('arrowdown')||Input.tap('s')||Input.tap('pad_down')||Input.tap('arrowleft')||Input.tap('a')||Input.tap('pad_left')||Input.tap('arrowright')||Input.tap('d')||Input.tap('pad_right')){ rival.choiceIdx=1-rival.choiceIdx; Audio.SFX.blip(); }
    const px0=VW/2-130, py0=VH*0.5-56, pw=260, ph=116;
    ctx.save();
    ctx.fillStyle='rgba(5,6,10,0.9)'; ctx.fillRect(px0,py0,pw,ph);
    ctx.strokeStyle=rival.tint; ctx.lineWidth=2; ctx.strokeRect(px0,py0,pw,ph);
    if(typeof msgText==='function') msgText(rival.name+' IS DISABLED', VW/2, py0+20, 12, '#ffd36b', 0.85, 1, 0.10);
    else { ctx.textAlign='center'; ctx.fillStyle='#ffd36b'; ctx.font='bold 13px "BOFmil", monospace'; ctx.fillText(rival.name+' IS DISABLED', VW/2, py0+22); }
    // options rendered as DIALOGUE text lines, with a clearly highlighted selected row
    const opts=['SPARE THEM','SHOOT THEM DOWN'];
    for(let i=0;i<2;i++){
      const sel=rival.choiceIdx===i, ry=py0+40+i*34, rh=28;
      // highlighted selection bar
      if(sel){ ctx.fillStyle=rgba(hx(rival.tint),0.32); ctx.fillRect(px0+10, ry, pw-20, rh);
        ctx.strokeStyle=rival.tint; ctx.lineWidth=2; ctx.strokeRect(px0+10, ry, pw-20, rh); }
      const label=(sel?'\u25B8 ':'   ')+opts[i];
      ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.fillStyle=sel?'#ffffff':'#9aa0aa'; ctx.font=(sel?'bold 14px':'12px')+' "BOFmil", monospace';
      ctx.fillText(label, VW/2, ry+rh/2);
      ctx.textBaseline='alphabetic';
    }
    ctx.restore();
    // select with fire/enter or gamepad A
    if(Input.tap('enter')||Input.tap(' ')||keybind.fire.some(k=>Input.tap(k))||Input.tap('pad_b0')||Input.tap('pad_b9')){
      Audio.SFX.select();
      if(rival.choiceIdx===0){ rival.phase='spare_dialogue'; if(typeof allyBank==='function') allyBank(rival.key); rival.dlgIdx=0; rival.dlgT=0; }
      else { rival.phase='shootdown_dialogue'; rival.t=0; rival.fadeT=0; }
    }
    return;
  }

  if(rival.phase==='player_spared'){
    // the player ran out of lives — the RIVAL spares them, then the run ends gracefully
    const lines=RIVAL_PLAYER_SPARED[rival.key]||["YOU'RE FINISHED, PILOT.","I'LL SEE YOU AROUND \u2014 IF YOU LIVE."];
    rival.dlgT+=dt;
    const appear=clamp(rival.dlgT/0.22,0,1);
    drawCommWindow({tint:rival.tint, name:rival.name, frameKey:'dlg_'+rival.key, portraitKey:pilotPortrait(rival.key,'idle'), cardKey:'card_'+rival.key, text:lines[rival.dlgIdx], appear});
    if(rival.dlgT>0.45){
      ctx.save(); ctx.globalAlpha=0.5+0.5*Math.sin(rival.dlgT*4); ctx.textAlign='center'; ctx.fillStyle='#cfd6e0'; ctx.font='9px "BOFmil", monospace';
      ctx.fillText(rival.dlgIdx<lines.length-1?'\u25B6':'PRESS FIRE / ENTER', VW/2, VH*0.34-24); ctx.restore();
      if(Input.tap('enter')||keybind.fire.some(k=>Input.tap(k))){
        Audio.SFX.blip();
        if(rival.dlgIdx<lines.length-1){ rival.dlgIdx++; rival.dlgT=0; }
        else {
          // losing the dogfight does NOT end the run — the rival spares you and you fly on to the next stage
          run.lives=Math.max(run.lives,1); player.dead=false; player.deathT=0;
          const _ns=(run.stage||2)+1; rival=null; beginStage(_ns);
        }
      }
    }
    return;
  }

  if(rival.phase==='spare_dialogue'){
    const lines=RIVAL_SPARE[rival.key]||["...","YOU'RE ALRIGHT, PILOT."];
    rival.dlgT+=dt;
    const appear=clamp(rival.dlgT/0.22,0,1);
    drawCommWindow({tint:rival.tint, name:rival.name, frameKey:'dlg_'+rival.key, portraitKey:pilotPortrait(rival.key,'idle'), cardKey:'card_'+rival.key, text:lines[rival.dlgIdx], appear});
    if(rival.dlgT>0.45){
      ctx.save(); ctx.globalAlpha=0.5+0.5*Math.sin(rival.dlgT*4); ctx.textAlign='center'; ctx.fillStyle='#cfd6e0'; ctx.font='9px "BOFmil", monospace';
      ctx.fillText(rival.dlgIdx<lines.length-1?'\u25B6':'PRESS FIRE / ENTER', VW/2, VH*0.34-24); ctx.restore();
      if(Input.tap('enter')||keybind.fire.some(k=>Input.tap(k))){
        Audio.SFX.blip();
        if(rival.dlgIdx<lines.length-1){ rival.dlgIdx++; rival.dlgT=0; }
        else {
          run.affiliation=run.affiliation||{}; run.allies=run.allies||[];
          run.affiliation[rival.key]='ally'; if(run.allies.indexOf(rival.key)<0) run.allies.push(rival.key);
          try{ localStorage.setItem('bof_affiliation', JSON.stringify(run.affiliation)); }catch(e){}
          rival.phase='reveal'; rival.t=0; rival.revealText='YOU GAINED AN ALLY!'; rival.revealCol='#8de23a';
        }
      }
    }
    return;
  }

  if(rival.phase==='shootdown_dialogue'){
    const line=RIVAL_SHOTDOWN[rival.key]||"NO \u2014 WAIT \u2014";
    const fadeIn=clamp(rival.t/1.3,0,1);
    ctx.save();
    const port=rivalPortrait('crash');
    if(typeof XART!=='undefined' && XART.rdy(port)){
      const im=XART.get(port), h=VH*0.62, w=h*(im.naturalWidth/im.naturalHeight);
      ctx.globalAlpha=fadeIn;
      if(rivalPortrait('crash')===('face_'+rival.key)){ ctx.filter='saturate(2) hue-rotate(-20deg)'; }  // distress tint for pilots without dedicated crash art
      ctx.drawImage(im, VW/2-w/2, VH*0.30-h/2, w, h);
      ctx.filter='none';
    }
    ctx.globalAlpha=Math.min(1,fadeIn*1.6);
    ctx.textAlign='center'; ctx.fillStyle='#ff4030'; ctx.font='bold 12px "BOFmil", monospace'; ctx.shadowColor='#000'; ctx.shadowBlur=4;
    ctx.fillText(line, VW/2, VH*0.30+VH*0.31+18);
    ctx.restore();
    if(rival.t>0.15 && !rival._crashSnd){ rival._crashSnd=true; Audio.SFX.hit(); }
    if(fadeIn>=1 && !rival.fadeT) rival.fadeT=rival.t;
    if(rival.fadeT && rival.t>rival.fadeT+0.9){
      rival.phase='crash_fade'; rival.t=0;
    }
    return;
  }

  if(rival.phase==='crash_fade'){
    if(rival.t<dt+0.001){ explode(rival.x,rival.y, Math.max(20, Math.max(rival.w||60,rival.h||60)*0.55), 'red'); Audio.SFX.expBig(); shake=Math.max(shake,16); flashScreen=Math.max(flashScreen||0,0.7); }
    if(rival.t>0.35 && rival.t<0.35+dt+0.001){ explode(rival.x+rnd(-24,24),rival.y+rnd(-18,18),50,'red'); }
    if(rival.t>1.6){
      run.affiliation=run.affiliation||{}; run.grudges=run.grudges||[];
      run.affiliation[rival.key]='enemy'; if(run.grudges.indexOf(rival.key)<0) run.grudges.push(rival.key);
      try{ localStorage.setItem('bof_affiliation', JSON.stringify(run.affiliation)); }catch(e){}
      rival.phase='reveal'; rival.t=0; rival.revealText='YOU GAINED AN ENEMY!'; rival.revealCol='#ff4030';
    }
    return;
  }

  if(rival.phase==='reveal'){
    const frac=clamp((rival.t-0.3)/1.0,0,1);
    typewriter(rival.revealText, frac, VW/2, VH*0.46, 20, rival.revealCol);
    if(frac>=1 && rival.t>1.6){
      ctx.save(); ctx.globalAlpha=0.5+0.5*Math.sin(rival.t*4); ctx.textAlign='center'; ctx.fillStyle='#cfd6e0'; ctx.font='9px "BOFmil", monospace';
      ctx.fillText('PRESS FIRE / ENTER', VW/2, VH*0.46+30); ctx.restore();
      if(Input.tap('enter')||keybind.fire.some(k=>Input.tap(k))){ Audio.SFX.select(); rival=null; beginStage(3); }
    }
    return;
  }
}
function drawRivalShip(){
  const key='ship_'+rival.key+(rival.bank>0.34?'_r':(rival.bank<-0.34?'_l':'_t'));
  const fallback='ship_'+rival.key;
  const k=(typeof XART!=='undefined'&&XART.rdy(key))?key:fallback;
  if(typeof XART!=='undefined' && XART.rdy(k)){
    const im=XART.get(k), w=44, h=w*(im.naturalHeight/im.naturalWidth);
    ctx.save(); ctx.translate(rival.x,rival.y); ctx.drawImage(im,-w/2,-h/2,w,h); ctx.restore();
  }
}
/* Post-boss flyover: continue flying forward over the SAME stage terrain the player was on,
   seamlessly extending the liquid so the cut to the results screen feels continuous. */
function _stageLiquidFrames(){
  // each stage's own animated liquid; sky/space have none (fall back to a scrolling starfield/void)
  if(run.stage===1) return ASSETS.water;
  if(run.stage===2) return ASSETS.lava;
  if(run.stage===3) return (ASSETS.iceWater&&ASSETS.iceWater.length)?ASSETS.iceWater:ASSETS.water;
  return null;
}
function drawFlyover(dt){
  /* STAGE EXIT, PER MIKE'S SPEC (drop 0801bd).

     "at the end of each level, simply show the player fly out the top of the
      screen, do not follow them, do not cut to no other scene just fade to
      black and into the stats end screen. simple."

     What this used to do, and why each part had to go:

       CUT TO ANOTHER SCENE - it threw away the stage the player was standing on
       and substituted a scrolling liquid bed, or a starfield on stage 5, or a
       blue gradient on everything else. That is the "other scene".  Now it
       redraws the REAL world, frozen, so the level you just beat is what you
       are looking at as you leave it.

       FOLLOWED THE SHIP - sx lerped from wherever the player was to VW/2, so the
       ship slid sideways to centre itself on the way out. The player's x is now
       held exactly where they left it.

       SHRANK INTO THE DISTANCE - ssc lerped 1.0 -> 0.55 and the ship faded at
       85%, which reads as flying AWAY from camera rather than off the top. Full
       scale the whole way, straight up, off the edge.

       SPEED STREAKS - part of the substituted scene, gone with it.

     The exit is: accelerate up and out (eased, so it reads as a takeoff rather
     than a constant slide), then the screen fades to black, then STAGECLEAR. */
  flyoverT+=dt;
  const FLY=1.25, FADE=0.75, DUR=FLY+FADE;
  /* HOVER, THEN LEAVE — AND THE WORLD KEEPS MOVING (drop 0801fe). Mike: "you
     should have my player hover for a while, cut to the music, and make the
     actual player fly off without being able to control him. You were doing this
     but leaving a static image of the current game state, this shouldnt be the
     case."

     drawWorld(0) passes dt=0, which freezes everything: the scroll stops, the
     liquid stops animating, the clouds stop. The ship then slides up a
     photograph. Passing the real dt keeps the level alive underneath while the
     player leaves it.

     A HOVER beat is added in front of the climb - the ship sits and idles while
     the last blasts die out, the music cuts, and only then does it go. */
  const HOVER=1.35;                              // seconds of hanging before the climb
  drawWorld(dt);                                 // live, not a snapshot
  if(!drawFlyover._musicCut && flyoverT>=HOVER*0.55){
    drawFlyover._musicCut=true;
    try{ if(Audio.stopMusic) Audio.stopMusic(); }catch(e){}
  }
  // 2) the player flies straight up and out. x is NOT touched.
  const fp=clamp(flyoverT/FLY,0,1);
  const ease=fp*fp;                                  // accelerates away, like a takeoff
  const pk=_pilotKey();
  const sx=(flyoverStartX!=null)?flyoverStartX:VW/2;  // held, never re-centred
  // the climb only starts after the hover; a small idle bob sells the hang
  const _climb=Math.max(0,(flyoverT-HOVER));
  const _ce=(typeof _ease==='function')?_ease(clamp(_climb/1.7,0,1)):clamp(_climb/1.7,0,1);
  const _base=(flyoverStartY!=null)?flyoverStartY:VH*0.78;
  const sy=(flyoverT<HOVER)
      ? _base+Math.sin(flyoverT*4.2)*3           // hovering
      : lerp(_base, -80, _ce);
  if(typeof XART!=='undefined' && XART.rdy('ship_'+pk)){
    const im=XART.get('ship_'+pk), w=44, h=w*(im.naturalHeight/im.naturalWidth);
    ctx.drawImage(im, sx-w/2, sy-h/2, w, h);          // full scale all the way out
    const theme=['#8de23a','#ff5a2a','#6fd0ff','#d8c068','#d07a3a'][clamp(run.stage-1,0,4)];
    if(sy>-40 && Math.random()<0.9){
      particles.push({x:sx+rnd(-4,4), y:sy+h*0.45, vx:rnd(-0.2,0.2), vy:rnd(2.5,4.5),
                      life:rnd(0.2,0.4), t:0, r:rnd(1,2), color:theme});
    }
  }
  // 3) fade to black once he is gone, then the stats screen. Nothing in between.
  if(flyoverT>FLY){
    ctx.fillStyle='rgba(0,0,0,'+clamp((flyoverT-FLY)/FADE,0,1).toFixed(3)+')';
    ctx.fillRect(0,0,VW,VH);
  }
  if(flyoverT>DUR){ flyoverT=0; setState(GS.STAGECLEAR); }
}
/* STAGE CLEAR */
function drawStageClear(dt){
  drawWorld(0);
  ctx.fillStyle='rgba(0,8,16,0.72)'; ctx.fillRect(0,0,VW,VH);
  const t=stateT; ctx.textAlign='center';
  // "STAGE COMPLETE!" flies in from the left with an overshoot
  const p=clamp(t/0.55,0,1), c1=1.70158, c3=c1+1;
  const e=1+c3*Math.pow(p-1,3)+c1*Math.pow(p-1,2);
  const cx=lerp(-VW*0.7, VW/2, e), sc=1+(1-p)*0.5;
  ctx.save(); ctx.translate(cx, VH/2-44); ctx.scale(sc,sc);
  msgText('STAGE',0,-8,26,null,0,1,0.10);
  msgText('COMPLETE!',0,24,26,null,0,1,0.10);
  ctx.restore();
  if(t>0.65){
    const a=clamp((t-0.65)/0.4,0,1); ctx.globalAlpha=a;
    msgText('SCORE '+pad(run.score,8),VW/2,VH/2+34,20,null,0,a,0.10);
    const codes=['FURY','IRON','DAM5','STRM','ORBT','TURB','SEWR','DETH'];
    if(run.stage<STAGES.length){ ctx.fillStyle='#cfd6e0'; ctx.font='10px "BOFmil", monospace'; ctx.fillText('NEXT STAGE PASSWORD: '+codes[run.stage],VW/2,VH/2+58); }
    ctx.globalAlpha=1;
  }
  if(t>1.2){ ctx.fillStyle='#9aa0aa'; ctx.font='9px "BOFmil", monospace'; ctx.globalAlpha=0.5+0.5*Math.sin(t*4); ctx.fillText('PRESS FIRE / ENTER',VW/2,VH/2+78); ctx.globalAlpha=1; }
  if(!drawStageClear._snd){ drawStageClear._snd=true; Audio.SFX.stageClear(); }
  /* the authored COMPLETE card, under the stats */
  if(typeof arcStageCard==='function'){
    const cc=arcStageCard(run.stage,'complete');
    if(cc) arcDraw(cc, VW/2, VH*0.86, 11, clamp((stateT-0.8)/1.6,0,1), '#8de23a');
  }
  if(t>0.9 && (Input.tap('enter')||keybind.fire.some(k=>Input.tap(k)))){
    drawStageClear._snd=false; run.lives=clamp(run.lives,0,9);
    if(run.stage>=STAGES.length){ triggerVictory(); }   // beat the last stage -> victory
    else beginStage(run.stage+1);
  }
}


/* GAME OVER */
function drawGameOver(dt){
  drawWorld(0);
  ctx.fillStyle='rgba(20,0,0,0.7)'; ctx.fillRect(0,0,VW,VH);
  ctx.textAlign='center';
  msgText('GAME OVER',VW/2,VH/2-20,32,null,0,1,0.10);
  ctx.fillStyle='#ffd36b'; ctx.font='bold 13px "BOFmil", monospace'; ctx.fillText('SCORE  '+pad(run.score,8),VW/2,VH/2+10);
  ctx.fillStyle='#9aa0aa'; ctx.font='10px "BOFmil", monospace'; ctx.fillText('HIGH  '+pad(highScore,8),VW/2,VH/2+28);
  /* THE AUTHORED GAME OVER (drop 0801ax). The doc bands these by how far the player got — stages
     1-3, 4-5, 6-7, 8, bonus — because dying early and dying at the finale should not read the
     same. Typed on so it lands after the score rather than competing with it. */
  if(typeof arcGameOver==='function'){
    const gc=arcGameOver(run.stage);
    if(gc) arcDraw(gc, VW/2, VH/2+66, 11, clamp((stateT-0.6)/1.4,0,1), '#c8d2e2');
  }
  if(stateT>1.4){ ctx.globalAlpha=0.5+0.5*Math.sin(stateT*4); ctx.fillStyle='#cfd6e0';
    ctx.fillText('ENTER = TITLE',VW/2,VH/2+64); ctx.globalAlpha=1; }
  if(stateT>1.2&&(Input.tap('enter')||Input.mouse.down)){ setState(GS.TITLE); menuIndex=0; Audio.startMusic('title'); }
}

/* VICTORY */
function drawVictory(dt){
  // ===== ENDING: credits roll over an endless terrain flyover — no fade to black =====
  drawVictory._scroll=(drawVictory._scroll||0)+dt*170;
  drawVictory._t=(drawVictory._t||0)+dt;
  const t=drawVictory._t;
  // cycle through every stage's terrain, ~9s each, crossfading between them
  const terrKeys=['terr_grass','terr_desert','terr_ice','terr_road','terr_war'];
  const SEG=9, seg=Math.floor(t/SEG)%terrKeys.length, segT=(t%SEG)/SEG;
  const nxt=(seg+1)%terrKeys.length;
  function tile(key,alpha){
    const im=(typeof XART!=='undefined'&&XART.rdy(key))?XART.get(key):null;
    if(!im) return false;
    const th=VW*(im.naturalHeight/im.naturalWidth), off=drawVictory._scroll%th;
    ctx.save(); ctx.globalAlpha=alpha;
    for(let y=-th+off; y<VH; y+=th) ctx.drawImage(im,0,y,VW,th);
    ctx.restore(); return true;
  }
  let drew=tile(terrKeys[seg],1);
  if(segT>0.85) drew=tile(terrKeys[nxt],(segT-0.85)/0.15)||drew;
  if(!drew && !drawAnimTerrain(ASSETS.water, drawVictory._scroll, 1.4)){ ctx.fillStyle='#0a1520'; ctx.fillRect(0,0,VW,VH); }
  // speed streaks
  ctx.save(); ctx.globalAlpha=0.22; ctx.strokeStyle='#ffffff'; ctx.lineWidth=1.2;
  for(let i=0;i<8;i++){ const sx=(i*61+drawVictory._scroll*2.2)%(VW+60)-30; ctx.beginPath(); ctx.moveTo(sx,0); ctx.lineTo(sx-8,VH); ctx.stroke(); }
  ctx.restore();
  // the player's ship, cruising with a gentle sway
  const pk=(typeof _pilotKey==='function')?_pilotKey():'axel';
  const shx=VW/2+Math.sin(t*0.5)*26, shy=VH*0.74+Math.sin(t*0.9)*8;
  if(typeof XART!=='undefined' && XART.rdy('ship_'+pk)){ const im=XART.get('ship_'+pk); const w=42,h=w*(im.naturalHeight/im.naturalWidth);
    ctx.save(); ctx.shadowColor='#ffd36b'; ctx.shadowBlur=8; ctx.drawImage(im,shx-w/2,shy-h/2,w,h); ctx.restore(); }
  // ---- scrolling credits ----
  const lines=[
    ['VICTORY!',22,'#ffd24a'],
    ['THE FURY IS UNLEASHED.',11,'#cfd6e0'],
    ['ALL 5 STAGES CLEARED.',11,'#cfd6e0'],
    ['',0,''],
    ['FINAL SCORE  '+pad(run.score,8),14,'#ffd36b'],
    ['DIFFICULTY: '+DIFF.name,10,'#9aa0aa'],
    ['',0,''],['',0,''],
    ['BULLETS OF FURY',18,'#ffd24a'],
    ['',0,''],
    ['COLEFORGE STUDIOS',14,'#eaf2ff'],
    ['',0,''],
    ['DESIGN',10,'#8b919c'],['MIKE',13,'#eaf2ff'],
    ['',0,''],
    ['ENGINE',10,'#8b919c'],['COLEFORGE PHOENIX ENGINE',12,'#eaf2ff'],
    ['',0,''],
    ['ART',10,'#8b919c'],['COLEFORGE',13,'#eaf2ff'],
    ['',0,''],
    ['MUSIC',10,'#8b919c'],['COLEFORGE AUDIO',13,'#eaf2ff'],
    ['',0,''],
    ['PILOTS',10,'#8b919c'],
    ['AXEL \u00b7 MAVERICK \u00b7 YURI \u00b7 DECKER',12,'#eaf2ff'],
    ['JUGGERNAUT \u00b7 FREEZER \u00b7 COLE',12,'#eaf2ff'],
    ['',0,''],['',0,''],
    ['RAIL SHOOTER EDITION',11,'#9aa0aa'],
    ['',0,''],['',0,''],
    ['THANK YOU FOR PLAYING',16,'#ffd24a']
  ];
  const LH=30, total=lines.length*LH+VH;
  const roll=Math.max(0,(t-1.5)*26)%total;   // loops forever
  ctx.save(); ctx.textAlign='center'; ctx.shadowColor='rgba(0,0,0,0.85)'; ctx.shadowBlur=5;
  const art=ASSETS.stageArt&&ASSETS.stageArt['2'];
  lines.forEach(function(l,i){
    if(!l[0]) return;
    const y=VH+i*LH-roll;
    if(y<-30||y>VH+30) return;
    const a=clamp(Math.min((y+20)/60,(VH-y+20)/60),0,1);
    ctx.globalAlpha=a;
    if(typeof msgText==='function'){ msgText(l[0],VW/2,y,Math.max(10,l[1]),l[2],0.85,ctx.globalAlpha,0.08); }
    else { ctx.fillStyle=l[2]; ctx.font=(l[1]>=13?'bold ':'')+l[1]+'px "BOFmil", monospace'; ctx.fillText(l[0],VW/2,y); }
  });
  ctx.restore();
  // return prompt appears after the roll has cycled once; the flight itself never ends
  if(t>6 && (Math.floor(t*1.4)%2)){ ctx.save(); ctx.textAlign='center'; ctx.fillStyle='#cfd6e0'; ctx.font='9px "BOFmil", monospace';
    ctx.shadowColor='#000'; ctx.shadowBlur=4; ctx.font='9px "BOFmil", monospace'; ctx.fillText('PRESS ENTER TO RETURN TO TITLE',VW/2,VH-12); ctx.restore(); }
  if(t>3 && (Input.tap('enter')||Input.mouse.down)){ drawVictory._t=0; drawVictory._scroll=0; setState(GS.TITLE); menuIndex=0; Audio.startMusic('title'); }
}

/* EXITED */
function drawExited(){
  ctx.fillStyle='#000'; ctx.fillRect(0,0,VW,VH);
  ctx.textAlign='center'; ctx.fillStyle='#5a606a'; ctx.font='bold 12px "BOFmil", monospace';
  ctx.fillText('THANKS FOR PLAYING',VW/2,VH/2-6);
  ctx.fillText('BULLETS OF FURY',VW/2,VH/2+12);
  ctx.font='9px "BOFmil", monospace'; ctx.fillText('press ENTER to return',VW/2,VH/2+40);
  if(Input.tap('enter')||Input.mouse.down){ setState(GS.TITLE); menuIndex=0; Audio.init(); Audio.startMusic('title'); }
}

/* ============================================================
   MAIN LOOP
   ============================================================ */
let last=performance.now();
function loop(now){
  if(Input.pollGamepad) Input.pollGamepad();
  let dt=(now-last)/1000; last=now;
  dt=Math.min(dt,0.05); stateT+=dt;
  ctx.imageSmoothingEnabled=false;
  /* A THROWN FRAME MUST NOT END THE GAME. The frame is rescheduled at the BOTTOM of this function,
     so any exception escaping the update or the draw stops that reschedule and the game locks up
     forever — no error on screen, just a frozen picture with the music still playing. That is the
     mechanism behind BOTH hard locks so far.
     UPDATE AND DRAW ARE BOTH GUARDED: the update carries far more logic than the draw, so leaving
     it outside would have left the larger half of the risk uncovered. A bad frame now costs one
     frame and is reported once, instead of costing the session. */
  try{
    if(state===GS.PLAY){ updatePlay(dt); }
  }catch(_updErr){
    if(!loop._uReported){ loop._uReported=true; try{ console.error('update error in state', state, _updErr); }catch(e){} }
  }
  /* INPUT BEFORE DRAW (drop 0801n). Belt and braces on the same bug.

     Menu input lives INSIDE the draw functions, which means a broken draw has always been able
     to take the menu with it. The drawImage guard above removes the usual cause, but the
     STRUCTURE is still fragile: any future throw in any menu draw would strand the player again.

     So the menu states now service their input FIRST, outside the draw's try block. Even if the
     draw dies completely, the menu still moves and the player can always leave. The draw calls it
     again at its usual place; a second call in the same frame is harmless because Input.tap is
     edge-triggered and has already been consumed. */
  /* The real handleTitleInput (patches.js) is EDGE-DETECTED on its own _pd/_pu latches, not on
     Input.tap, so calling it here as well as inside the draw moves the cursor exactly once per
     press. The point of calling it here is that this call is outside the draw's try block: if the
     draw dies, the menu still moves and the player can always leave. */
  try{
    if(state===GS.TITLE && typeof handleTitleInput==='function') handleTitleInput();
  }catch(_inErr){}
  try{
    if(state==='exited'){ drawExited(); }
    else { drawScene(dt); }
  }catch(_frameErr){
    if((typeof DBG!=='undefined' && DBG.verbose) || !loop._reported){ loop._reported=true; try{ console.error('draw error in state', state, _frameErr); }catch(e){} }
  }
  /* SELECTION FLASH — painted in the FRAME LOOP, over whatever the scene drew.
     It was previously injected INTO drawScene's dispatch by splitting the switch in two, which
     left the second half as `switch(0){ case -1: ... }` — a switch that can never match. That
     silently killed rendering for PLAY, MODESEL, STAGESEL, STAGECLEAR, GAMEOVER, CONTINUE,
     VICTORY, RIVAL and FLYOVER: audio and input kept running, nothing drew. Never split a
     dispatch to inject an overlay; draw the overlay after the dispatch returns. */
  /* DIAGNOSTIC READOUT ON EVERY SCREEN (drop 0724dj).
     The probe was on the title only, so when Mike could not reach the title he could not see it
     either — the instrument was hidden behind the fault it was meant to diagnose. It now draws
     after the dispatch, on every state, so wherever he is stuck one photograph gives me the state
     name and whether events are arriving. Remove this block when the fault is found. */
  /* LIVE MENU DIAGNOSTIC (drop 0801r). Toggle with the ` key (backtick) — off by default, so it
     never sits on Mike's screen uninvited. It answers the ONE question the static analysis cannot:
     on his machine, at the moment the cursor will not move, WHICH stage is failing.

       raw     is Input.down('arrowdown') true while the key is held?     -> the browser/keys work
       tap     did Input.menuDown() fire?                                 -> the keybind path works
       calls   how many times handleTitleInput ran this frame             -> it is being called
       idx     menuIndex                                                  -> it is being moved

     If raw is 0 while pressing, the key never reaches the game. If raw is 1 and idx is frozen,
     the handler is being skipped or throwing. Either answer ends the guessing. */
  if(typeof window!=='undefined' && window.__menudiag && typeof ctx!=='undefined' &&
     (state===GS.TITLE || state===GS.MODESEL || state===GS.PILOT)){
    try{
      const D=window.__menudiag;
      ctx.save(); ctx.font='11px "BOFmil", monospace'; ctx.textAlign='left';   /* drop 0801gs */
      ctx.fillStyle='rgba(0,0,0,0.78)'; ctx.fillRect(2,2,250,52);
      ctx.fillStyle='#8dff9a';
      ctx.fillText('raw d/u '+(Input.down('arrowdown')?1:0)+'/'+(Input.down('arrowup')?1:0)
                  +'   calls '+(D.calls|0)+'   idx '+(typeof menuIndex!=='undefined'?menuIndex:'-'), 6, 14);
      ctx.fillText('lastMove '+(D.lastMove||'-')+'   err '+(D.err||'none').slice(0,28), 6, 27);
      ctx.fillText('handler '+(typeof handleTitleInput)+'  state '+String(state), 6, 40);
      ctx.fillStyle='#9fb0cd';
      ctx.fillText('` toggles this readout', 6, 51);
      ctx.restore();
      D.calls=0;
    }catch(_){}
  }
  /* THE PROBE WAS NEVER GATED ON DBG.probe (drop 0801p). Mike has asked twice to have his screen
     back and it kept coming up, because the condition is `window.__inp`, which is set
     unconditionally at input setup and is therefore always truthy. Setting DBG.probe=false did
     nothing at all. Gate it properly. */
  if(typeof DBG!=='undefined' && DBG.probe &&
     typeof window!=='undefined' && window.__inp && typeof ctx!=='undefined'){
    const P=window.__inp;
    ctx.save();
    ctx.setTransform(SS,0,0,SS,0,0);
    ctx.textAlign='left'; ctx.font='9px "BOFmil", monospace';
    /* TOP-LEFT, not bottom. The cabinet layout puts the canvas inside #game-frame with
       overflow:hidden, so anything at the very bottom of a 960x1024 backing can be cropped out of
       view — which is a good way to hide the instrument that is supposed to be visible. */
    ctx.fillStyle='rgba(0,0,0,0.72)'; ctx.fillRect(2,2,214,40);
    ctx.fillStyle=(P.key+P.mdown+P.mmove)>0 ? '#8dff9a' : '#ff6a5a';
    ctx.fillText('state '+String(state)+'   kd'+P.key+' ku'+P.kup+' md'+P.mdown+' mm'+P.mmove, 6, 14);
    ctx.fillText('last '+P.lastKey+'   at '+P.lastXY, 6, 25);
    ctx.fillStyle='#9fb0cd';
    ctx.fillText('menu '+(typeof menuIndex!=='undefined'?menuIndex:'-')+'   PHOTOGRAPH THIS', 6, 36);
    ctx.restore();
  }
  if(typeof selFlashTick==='function') selFlashTick(dt);
  if(typeof selFlashDraw==='function') selFlashDraw();
  if(hudctx){ hudctx.clearRect(0,0,VW,HUDH); if(state===GS.PLAY||state==='paused'){ if(typeof drawHUDStrip==='function') drawHUDStrip(hudctx); } }
  /* SUSTAINED SFX BEDS (drop 0730a). Held weapons keep their loop alive by calling loopOn every
     time they fire; this is what fades one out once they stop. It has to run OUTSIDE the play
     state too, or a jet held while the player dies or pauses would roar forever. */
  if(typeof Snd!=='undefined' && Snd && Snd.loopTick){
    if(state===GS.PLAY) Snd.loopTick(dt); else Snd.loopStopAll();
  }
  Input.clearTaps();
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

// safety: clear taps each frame handled above; ensure first-interaction audio
window.addEventListener('keydown',()=>{ try{ Audio.init(); }catch(_){} },{once:true});
window.addEventListener('pointerdown',()=>{ try{ Audio.init(); }catch(_){} },{once:true});

/* ===== real-sample audio (samples + music), re-points Audio.SFX + startMusic ===== */
const Snd=(function(){
  if(!window.BOFA||!window.Audio) return null;
  function c01(x){ return Math.max(0,Math.min(1,x||0)); }
  // music at full level, SFX mixed LOWER so music is clearly audible over the effects
  const A={ vol:{master:1.0,music:1.0,sfx:0.42,voice:0.85}, pools:{}, music:{}, cur:null };
  for(const name in BOFA.sfx){ const uri='data:audio/mpeg;base64,'+BOFA.sfx[name];
    const list=[]; for(let i=0;i<3;i++){ const a=new window.Audio(); a.src=uri; a.preload='auto'; list.push(a); }
    A.pools[name]={list,i:0}; }
  for(const name in BOFA.music){ const m=new window.Audio(); m.src='data:audio/mpeg;base64,'+BOFA.music[name]; m.loop=true; m.preload='auto'; A.music[name]=m; }
  A.VOICE_SET={continueVO:1,countdown:1,restrictedarea:1,enemyunits:1,enemyunit:1,over:1,goodluck:1,announce:1,selectpilot:1};

  /* ---- TONE SHAPING (drop 0730a) -------------------------------------------
     Mike: "the missile and firewave sounds are harsh to the ears."

     I first blamed the synth fallback and was wrong — BOFA.sfx ships REAL missile and firewall
     samples, and the loader below re-points Audio.SFX at them, so the grenade() fallback never
     runs. The harshness is in the samples and in how often they are retriggered, which needs
     three separate fixes:

       g    a straight level cut, and the one that always works
       lp   a lowpass — this is what actually takes the edge off, and it needs WebAudio
       min  a minimum retrigger gap, so a held or rapid weapon cannot stack copies of the same
            attack transient across the 3-element pool

     HTMLAudioElement has no filtering, so the lowpass is done by routing the element through a
     MediaElementAudioSourceNode. That has a real failure mode: once an element is attached to a
     graph it ONLY outputs through that graph, so a suspended AudioContext would make the sound
     silent rather than soft. Silent is worse than harsh. So the graph is only ever built while
     the context is actually running, and any throw drops that sound back to plain playback for
     good — the level cut and the throttle still apply either way. */
  A.TAME = {
    missile:  {g:0.62, lp:4200, min:0.11},
    firewall: {g:0.58, lp:3400, min:0.10},
  };
  A._ctx=null; A._nodes={}; A._bad={}; A._last={};
  A._audioCtx=function(){
    if(A._ctx) return A._ctx;
    try{ const C=window.AudioContext||window.webkitAudioContext; if(!C) return null; A._ctx=new C(); }catch(e){ A._ctx=null; }
    return A._ctx;
  };
  A._shape=function(a,name,cfg){
    if(!cfg.lp || A._bad[name]) return false;
    if(a._bofNode) return true;
    const ctxA=A._audioCtx();
    if(!ctxA || ctxA.state!=='running'){ try{ if(ctxA&&ctxA.resume) ctxA.resume(); }catch(e){} return false; }
    try{
      const srcN=ctxA.createMediaElementSource(a);
      const lp=ctxA.createBiquadFilter(); lp.type='lowpass';
      lp.frequency.value=cfg.lp; lp.Q.value=0.7;
      const sh=ctxA.createBiquadFilter(); sh.type='highshelf';
      sh.frequency.value=2600; sh.gain.value=-6;
      const g=ctxA.createGain(); g.gain.value=1;
      srcN.connect(lp); lp.connect(sh); sh.connect(g); g.connect(ctxA.destination);
      a._bofNode=g; return true;
    }catch(e){ A._bad[name]=1; return false; }
  };
  A.play=function(name,vol){ const p=A.pools[name]; if(!p) return;
    const cfg=A.TAME[name];
    if(cfg && cfg.min){                                   // retrigger throttle
      const t=(window.performance&&performance.now?performance.now():Date.now())/1000;
      if(A._last[name]!=null && t-A._last[name] < cfg.min) return;
      A._last[name]=t;
    }
    const a=p.list[p.i]; p.i=(p.i+1)%p.list.length;
    const ch=A.VOICE_SET[name] ? (A.vol.voice!=null?A.vol.voice:1) : A.vol.sfx;
    const gm=cfg?cfg.g:1;
    if(cfg) A._shape(a,name,cfg);
    try{ a.currentTime=0; a.volume=c01((vol==null?1:vol)*gm*ch*A.vol.master); const pr=a.play(); if(pr&&pr.catch)pr.catch(function(){}); }catch(e){} };

  /* ---- SUSTAINED LOOPS -----------------------------------------------------
     For HELD weapons. loopOn() is safe to call every frame: it starts the bed once and then just
     keeps the fade climbing. loopOff() fades it out and pauses, so releasing the button does not
     cut the sound off with a click. Dedicated elements, so the round-robin pool is untouched. */
  A.loops={};
  A.loopOn=function(name,vol){
    let L=A.loops[name];
    if(!L){
      const src=A.pools[name]; if(!src||!src.list.length) return;
      const a=new window.Audio(); a.src=src.list[0].src; a.loop=true; a.preload='auto';
      L=A.loops[name]={el:a, on:false, lvl:0, want:(vol==null?1:vol)};
    }
    L.want=(vol==null?1:vol);
    L.hold=2;                                             // frames of grace before the fade-out starts
    if(!L.on){
      L.on=true;
      const cfg=A.TAME[name]; if(cfg) A._shape(L.el,name,cfg);
      try{ L.el.currentTime=0; const pr=L.el.play(); if(pr&&pr.catch)pr.catch(function(){}); }catch(e){}
    }
  };
  A.loopOff=function(name){ const L=A.loops[name]; if(L) L.hold=0; };
  A.loopTick=function(dt){
    for(const n in A.loops){
      const L=A.loops[n], cfg=A.TAME[n], gm=cfg?cfg.g:1;
      if(L.hold>0){ L.hold--; L.lvl=Math.min(1, L.lvl+dt*7); }
      else { L.lvl=Math.max(0, L.lvl-dt*5); if(L.lvl<=0 && L.on){ L.on=false; try{ L.el.pause(); }catch(e){} } }
      try{ L.el.volume=c01(L.lvl*L.want*gm*A.vol.sfx*A.vol.master); }catch(e){}
    }
  };
  A.loopStopAll=function(){ for(const n in A.loops){ const L=A.loops[n]; L.hold=0; L.lvl=0; L.on=false; try{ L.el.pause(); }catch(e){} } };
  A.startMusic=function(name){ const m=A.music[name]; if(!m) return; if(A.cur===m&&!m.paused) return; A.stopMusic(); A.cur=m;
    try{ m.playbackRate=(typeof timeScale!=='undefined'&&timeScale<1)?timeScale:1; if('preservesPitch'in m)m.preservesPitch=(timeScale>=1); }catch(e){}
    try{ m.volume=c01(A.vol.music*A.vol.master); m.currentTime=0; const pr=m.play(); if(pr&&pr.catch)pr.catch(function(){}); }catch(e){} };
  A.stopMusic=function(){ if(A.cur){ try{A.cur.pause();}catch(e){} A.cur=null; } };
  A.stopVoice=function(){ for(const nm in A.VOICE_SET){ const p=A.pools[nm]; if(p&&p.list){ for(const a of p.list){ try{ a.pause(); a.currentTime=0; }catch(e){} } } } };
  A.setVol=function(k,v){ if(A.vol[k]!=null){ A.vol[k]=c01(v); if(A.cur) A.cur.volume=c01(A.vol.music*A.vol.master); } };
  return A;
})();
if(Snd){
  /* EVERY REGISTERED SOUND GETS A HANDLE.
     This used to be a HARDCODED WHITELIST of 33 names, so only those were re-pointed at the real
     samples. Every sound added since — the 18 that were silent, the helix set, the boss stinger,
     the ally cues, the race, the map — was registered in BOFA.sfx, had a real file on disk, and
     was called correctly at the right moment... and did nothing, because no handle was ever built
     for it. `if(Audio.SFX.helixBurst) Audio.SFX.helixBurst();` is silently false when the method
     does not exist. That is why "very few from the pack made it through".
     Driven off BOFA.sfx now, so registering a sound is all it takes. */
  for(const m in BOFA.sfx){ if(Audio.SFX){ Audio.SFX[m]=(function(n){ return function(){ Snd.play(n); }; })(m); } }
  Audio.startMusic=function(n){ Snd.startMusic(n); };
  Audio.stopMusic=function(){ Snd.stopMusic(); };
  Audio.stopVoice=function(){ if(Snd.stopVoice)Snd.stopVoice(); };
  const _setVol=Audio.setVol;
  Audio.setVol=function(k,v){ try{ if(_setVol)_setVol(k,v); }catch(e){} Snd.setVol(k,v); };
  try{ Snd.setVol('master',Audio.getVol('master')); Snd.setVol('music',Audio.getVol('music')); Snd.setVol('sfx',Audio.getVol('sfx')); }catch(e){}
}


/* CONTINUE — 10s countdown. VO says "continue?" then counts 10..1 in sync with the on-screen
   number, then "GAME" + over.mp3 at zero. Continuing cancels any pending VO. */
function _stopContinueVO(){
  drawContinue._vo=false;
  // silence the number-tick VO channel if it's mid-count
  try{ if(Audio.stopVoice)Audio.stopVoice(); }catch(e){}
}
function drawContinue(dt){
  drawWorld(0);
  if(!drawContinue._vo){ drawContinue._vo=true; drawContinue._overPlayed=false; drawContinue._t0=stateT;
    // play the countdown clip ONCE (no separate 'continue' VO first); numbers match its length
    if(Audio.SFX&&Audio.SFX.countdown)Audio.SFX.countdown();
  }
  ctx.fillStyle='rgba(8,0,0,0.72)'; ctx.fillRect(0,0,VW,VH);
  const art=curArt();
  // audio clip is ~16s: a short lead-in, then it counts 10..1. Pace the numbers to match.
  const LEADIN=1.4, PERNUM=1.45, TOTAL=LEADIN+10*PERNUM;
  if(stateT>=TOTAL){
    if(!drawContinue._overPlayed){ drawContinue._overPlayed=true; if(Audio.SFX&&Audio.SFX.over)Audio.SFX.over(); }
    drawContinue._vo=false; triggerGameOver(); return;
  }
  const elapsedNums=Math.max(0,(stateT-LEADIN)/PERNUM);
  const num=Math.max(1,10-Math.floor(elapsedNums));
  const secs=TOTAL-stateT;
  // numbers change once per second, synced to the single countdown clip (no re-triggering the clip)
  if(drawContinue._lastNum!==num){ drawContinue._lastNum=num; if(num<=3) Audio.SFX.blip(); }
  if(artReady(art)){
    stageText(art,'CONTINUE?',VW/2,VH*0.28,30,art.warmFont?null:'#ff5a1a',0.78,1,0.12);
    const f=secs-Math.floor(secs), pop=1+(1-f)*0.35;
    stageText(art,String(num),VW/2,VH*0.55,92*pop,null,null,1,0.08);
  } else {
    ctx.textAlign='center'; msgText('CONTINUE?',VW/2,VH*0.30,30,null,0,1,0.12);
    ctx.fillStyle='#fff'; ctx.font='bold 90px "Arial Black",sans-serif'; ctx.fillText(String(num),VW/2,VH*0.62);
  }
  if(stateT>0.3 && Math.floor(stateT*2)%2){ ctx.textAlign='center'; ctx.fillStyle='#cfd6e0'; ctx.font='bold 11px "BOFmil", monospace'; ctx.fillText('PRESS FIRE TO CONTINUE',VW/2,VH*0.74); }
  if(stateT>0.3 && (Input.tap('enter')||keybind.fire.some(k=>Input.tap(k))||Input.mouse.down)){
    _stopContinueVO();   // CANCEL the countdown VO when the player continues
    if(Audio.SFX&&Audio.SFX.goodluck)Audio.SFX.goodluck();
    drawContinue._b=-1; drawContinue._lastNum=99;
    run.lives=DIFF.startLives; run.bombs=Math.max(run.bombs,1);
    player.dead=false; player.deathT=0; player.reset(); player.invuln=140;
    eBullets.length=0;
    setState(GS.PLAY);
  }
}


